-- SynapseDC DC-STORE schema (MySQL 8.0.16+, InnoDB, utf8mb4)
-- Generated by scripts/db/build_schema.py on 2026-11-12; edit the generator, not this file.
-- Source: BRD 10.4 (DATA-017…022). Physical / facility records, holds, customers, alarms, incidents, changes,
-- addresses, projects and contracts are NOT here: they are read and written through the platform module APIs.
-- Ids of records owned by a module are stored as that module's id (prefix INV_ / IPL_ / IPM_ / ITSM_ / ALR_ / BSS_ /
-- PRJ_ / SCM_ / PE_); they cannot carry FOREIGN KEYs because the records live in other databases (DATA-019).
-- No AUD tables: the platform keeps the audit trail of every insert / update / delete (DATA-021).
-- Times are UTC. Money is DECIMAL with a CURRENCY_CODE column (planner figures are USD, suffix _USD).

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- BUSINESS_MODEL: Vocabulary and service levels per business model (persona); screens read every customer / service / money word from here (BRD DATA-011).
-- Related tables: BUSINESS_MODEL ← MACD_CATALOGUE_ITEM_MODEL, IMPORT_BATCH
-- Domain: A. Configuration and reference data · Updated: 2026-11-12
CREATE TABLE `BUSINESS_MODEL` (
  `BUSINESS_MODEL_ID` SMALLINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of BUSINESS_MODEL',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `BUSINESS_MODEL_CODE` ENUM('colocation','neocloud','cloud','enterprise','network') NOT NULL COMMENT 'Business model key',
  `LABEL` VARCHAR(200) NOT NULL COMMENT 'Display name, e.g. Colocation',
  `SHORT_LABEL` VARCHAR(50) NOT NULL COMMENT 'Short name for chips',
  `TAGLINE` VARCHAR(200) NULL COMMENT 'One-line description',
  `EDGE_DEVICE_PREFIX` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Prefix of WAN-edge device names in this model (e.g. PE, BDR)',
  `SLA_PREMIUM_PCT` DECIMAL(6,3) NOT NULL COMMENT 'Availability target of premium services (%)',
  `SLA_STANDARD_PCT` DECIMAL(6,3) NOT NULL COMMENT 'Availability target of standard services (%)',
  `CUSTOMER_WORD` VARCHAR(50) NOT NULL COMMENT 'Word for one customer (customer, tenant, business unit ...)',
  `CUSTOMERS_WORD` VARCHAR(50) NOT NULL COMMENT 'Plural of CUSTOMER_WORD',
  `SERVICE_WORD` VARCHAR(50) NOT NULL COMMENT 'Word for one service',
  `SERVICES_WORD` VARCHAR(50) NOT NULL COMMENT 'Plural of SERVICE_WORD',
  `EQUIPMENT_WORD` VARCHAR(50) NOT NULL COMMENT 'Word for customer equipment',
  `PREMIUM_WORD` VARCHAR(50) NOT NULL COMMENT 'Word for the premium tier',
  `CAPACITY_LABEL` VARCHAR(100) NOT NULL COMMENT 'Label of the capacity measure',
  `PRIMARY_UNIT` ENUM('Mbps','kW','vCPU','TB','GPU','users','cabinets','hours') NOT NULL COMMENT 'Unit capacity is sold in',
  `HANDOFF_WORD` VARCHAR(50) NOT NULL COMMENT 'Word for the customer hand-off point',
  `MONEY_NOUN` VARCHAR(50) NOT NULL COMMENT 'Money noun (Revenue, Business value ...)',
  `MONEY_IMPACT_WORD` VARCHAR(50) NOT NULL COMMENT 'Money impact phrase (Revenue impact, Business impact ...)',
  `MONEY_LOST_WORD` VARCHAR(50) NOT NULL COMMENT 'Lost-money phrase',
  `MONEY_CREDITS_WORD` VARCHAR(50) NOT NULL COMMENT 'SLA credit phrase (SLA credits, OLA rebates ...)',
  `MONEY_BASE_WORD` VARCHAR(50) NOT NULL COMMENT 'Base charge phrase',
  `MONEY_BILLING_WORD` VARCHAR(50) NOT NULL COMMENT 'Billing phrase',
  `IS_ENABLED` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = business model offered to this tenant',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`BUSINESS_MODEL_ID`),
  UNIQUE KEY `UK_BUSINESS_MODEL_TENANT_ID_BUSINESS_MODEL_CODE` (`TENANT_ID`, `BUSINESS_MODEL_CODE`),
  UNIQUE KEY `UK_BUSINESS_MODEL_TENANT_ID_BUSINESS_MODEL_ID` (`TENANT_ID`, `BUSINESS_MODEL_ID`),
  CONSTRAINT `CK_BUSINESS_MODEL_01` CHECK (SLA_PREMIUM_PCT BETWEEN 0 AND 100),
  CONSTRAINT `CK_BUSINESS_MODEL_02` CHECK (SLA_STANDARD_PCT BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Vocabulary and service levels per business model (persona); screens read every customer / service / money word from here (BRD DATA-011).';

-- GEOGRAPHY: Country-level formatting and grid factors: currency, number locale, date style, grid carbon factor, map bounds.
-- Related tables: GEOGRAPHY ← GEOGRAPHY_REGION, POWER_RATE_CARD
-- Domain: A. Configuration and reference data · Updated: 2026-11-12
CREATE TABLE `GEOGRAPHY` (
  `GEOGRAPHY_ID` SMALLINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of GEOGRAPHY',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `GEOGRAPHY_CODE` VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Geography key (in, us)',
  `NAME` VARCHAR(200) NOT NULL COMMENT 'Display name',
  `COUNTRY_CODE` CHAR(2) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ISO 3166-1 alpha-2 country code',
  `CURRENCY_CODE` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ISO 4217 currency of money shown in this geography',
  `CURRENCY_SYMBOL` VARCHAR(4) NOT NULL COMMENT 'Currency symbol',
  `NUMBER_LOCALE` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'BCP 47 locale for number formatting (en-IN, en-US)',
  `DATE_STYLE` ENUM('dmy','mdy') NOT NULL COMMENT 'Date order',
  `FX_PER_INR` DECIMAL(12,6) NOT NULL COMMENT 'Conversion from rupee reference constants (1 for India)',
  `GRID_CO2_KG_PER_KWH` DECIMAL(6,4) NOT NULL COMMENT 'National grid emission factor, kg CO2 per kWh',
  `GRID_FACTOR_SOURCE` VARCHAR(200) NOT NULL COMMENT 'Source of the grid factor (e.g. CEA v19, eGRID 2022)',
  `MAP_SOUTH_LAT` DECIMAL(9,6) NOT NULL COMMENT 'Map bounds: south latitude',
  `MAP_WEST_LNG` DECIMAL(9,6) NOT NULL COMMENT 'Map bounds: west longitude',
  `MAP_NORTH_LAT` DECIMAL(9,6) NOT NULL COMMENT 'Map bounds: north latitude',
  `MAP_EAST_LNG` DECIMAL(9,6) NOT NULL COMMENT 'Map bounds: east longitude',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`GEOGRAPHY_ID`),
  UNIQUE KEY `UK_GEOGRAPHY_TENANT_ID_GEOGRAPHY_CODE` (`TENANT_ID`, `GEOGRAPHY_CODE`),
  UNIQUE KEY `UK_GEOGRAPHY_TENANT_ID_GEOGRAPHY_ID` (`TENANT_ID`, `GEOGRAPHY_ID`),
  CONSTRAINT `CK_GEOGRAPHY_01` CHECK (MAP_SOUTH_LAT BETWEEN -90 AND 90),
  CONSTRAINT `CK_GEOGRAPHY_02` CHECK (MAP_NORTH_LAT BETWEEN -90 AND 90),
  CONSTRAINT `CK_GEOGRAPHY_03` CHECK (MAP_WEST_LNG BETWEEN -180 AND 180),
  CONSTRAINT `CK_GEOGRAPHY_04` CHECK (MAP_EAST_LNG BETWEEN -180 AND 180),
  CONSTRAINT `CK_GEOGRAPHY_05` CHECK (MAP_SOUTH_LAT < MAP_NORTH_LAT),
  CONSTRAINT `CK_GEOGRAPHY_06` CHECK (GRID_CO2_KG_PER_KWH >= 0),
  CONSTRAINT `CK_GEOGRAPHY_07` CHECK (FX_PER_INR > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Country-level formatting and grid factors: currency, number locale, date style, grid carbon factor, map bounds.';

