-- GPU_MODEL: GPU / accelerator catalogue: hardware facts, telemetry source and counter set, price factor and the instance type sold (BRD BRULE-GPU-02, -19, -20).
-- Related tables: GPU_MODEL ← GPU_MODEL_SERVER, GPU_MODEL_BENCHMARK
-- Domain: A. Configuration and reference data · Updated: 2026-11-12
CREATE TABLE `GPU_MODEL` (
  `GPU_MODEL_ID` SMALLINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of GPU_MODEL',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `MODEL_CODE` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Model key as reported by the exporter, e.g. H100 SXM 80 GB',
  `SILICON_VENDOR` ENUM('NVIDIA','Intel') NOT NULL COMMENT 'Silicon vendor',
  `SHORT_NAME` VARCHAR(16) NOT NULL COMMENT 'Short name, e.g. H100',
  `ARCHITECTURE` VARCHAR(50) NOT NULL COMMENT 'Architecture (Hopper, Blackwell, Gaudi 2 ...)',
  `MEMORY_GB` SMALLINT UNSIGNED NOT NULL COMMENT 'On-package memory, GB',
  `MEMORY_TYPE` VARCHAR(16) NOT NULL COMMENT 'Memory type (HBM3, HBM2e, GDDR6)',
  `TDP_W` SMALLINT UNSIGNED NOT NULL COMMENT 'Board power limit, W',
  `FORM_FACTOR` VARCHAR(16) NOT NULL COMMENT 'SXM, OAM or PCIe',
  `SCALE_UP_LINK` VARCHAR(50) NOT NULL COMMENT 'In-node scale-up link (NVLink 4, RoCE on card ...)',
  `SCALE_UP_LINK_SHORT` VARCHAR(16) NOT NULL COMMENT 'Short name of the scale-up link',
  `SCALE_OUT_FABRIC` VARCHAR(50) NOT NULL COMMENT 'Scale-out fabric (InfiniBand NDR, RoCE)',
  `CLOCK_MIN_MHZ` SMALLINT UNSIGNED NOT NULL COMMENT 'Lowest core clock, MHz',
  `CLOCK_MAX_MHZ` SMALLINT UNSIGNED NOT NULL COMMENT 'Highest core clock, MHz',
  `IDLE_MIN_W` SMALLINT UNSIGNED NOT NULL COMMENT 'Idle power, low end, W',
  `IDLE_MAX_W` SMALLINT UNSIGNED NOT NULL COMMENT 'Idle power, high end, W',
  `MEMORY_CLOCK_MHZ` SMALLINT UNSIGNED NULL COMMENT 'Memory clock under load, MHz; NULL when the exporter does not report it',
  `MEMORY_IDLE_CLOCK_MHZ` SMALLINT UNSIGNED NULL COMMENT 'Memory clock at idle, MHz',
  `PRIMARY_USE` ENUM('training','inference') NOT NULL COMMENT 'Workload the model is sold for',
  `PRICE_FACTOR` DECIMAL(6,3) NOT NULL COMMENT 'Price relative to an H100 GPU-hour (H100 = 1)',
  `TELEMETRY_SOURCE` VARCHAR(100) NOT NULL COMMENT 'Exporter that reports it (DCGM exporter, habanalabs exporter, XPU Manager)',
  `COUNTER_SET` ENUM('dcgm','habana','xpu') NOT NULL COMMENT 'Counter family the screens expect; missing counters show —',
  `IS_POWER_KNOWN` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = node power is reported and counted in power / occupancy totals (BRULE-GPU-20)',
  `DRIVER_CURRENT` VARCHAR(50) NOT NULL COMMENT 'Current approved driver version',
  `DRIVER_OLD` VARCHAR(50) NULL COMMENT 'Previous driver version that counts as drift',
  `FIRMWARE` VARCHAR(50) NULL COMMENT 'Approved firmware version',
  `OS_IMAGE` VARCHAR(50) NULL COMMENT 'Approved host OS image',
  `LAUNCH_YEAR` SMALLINT UNSIGNED NOT NULL COMMENT 'Year the model launched',
  `GPUS_PER_NODE` TINYINT UNSIGNED NOT NULL DEFAULT 8 COMMENT 'Accelerators per server node',
  `INSTANCE_VCPU` SMALLINT UNSIGNED NOT NULL COMMENT 'Instance type: vCPUs per node',
  `INSTANCE_RAM_GB` SMALLINT UNSIGNED NOT NULL COMMENT 'Instance type: RAM per node, GB',
  `INSTANCE_NVME_TB` DECIMAL(6,2) NOT NULL COMMENT 'Instance type: local NVMe per node, TB',
  `INSTANCE_NET_GBPS` SMALLINT UNSIGNED NOT NULL COMMENT 'Instance type: front-end network per node, Gbps',
  `IS_ACTIVE` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = offered in pickers and plans',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`GPU_MODEL_ID`),
  UNIQUE KEY `UK_GPU_MODEL_TENANT_ID_MODEL_CODE` (`TENANT_ID`, `MODEL_CODE`),
  UNIQUE KEY `UK_GPU_MODEL_TENANT_ID_GPU_MODEL_ID` (`TENANT_ID`, `GPU_MODEL_ID`),
  CONSTRAINT `CK_GPU_MODEL_01` CHECK (CLOCK_MIN_MHZ <= CLOCK_MAX_MHZ),
  CONSTRAINT `CK_GPU_MODEL_02` CHECK (IDLE_MIN_W <= IDLE_MAX_W),
  CONSTRAINT `CK_GPU_MODEL_03` CHECK (IDLE_MAX_W <= TDP_W),
  CONSTRAINT `CK_GPU_MODEL_04` CHECK (PRICE_FACTOR > 0),
  CONSTRAINT `CK_GPU_MODEL_05` CHECK (GPUS_PER_NODE > 0),
  CONSTRAINT `CK_GPU_MODEL_06` CHECK (INSTANCE_NVME_TB >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='GPU / accelerator catalogue: hardware facts, telemetry source and counter set, price factor and the instance type sold (BRD BRULE-GPU-02, -19, -20).';

