  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`GPU_MODEL_BENCHMARK_ID`),
  UNIQUE KEY `UK_GPU_MODEL_BENCHMARK_TENANT_ID_GPU_MODEL_ID` (`TENANT_ID`, `GPU_MODEL_ID`),
  CONSTRAINT `CK_GPU_MODEL_BENCHMARK_01` CHECK (HBM_TBS > 0),
  CONSTRAINT `CK_GPU_MODEL_BENCHMARK_02` CHECK (BUS_GBS > 0),
  CONSTRAINT `CK_GPU_MODEL_BENCHMARK_03` CHECK (HELD_BACK_BELOW_PCT BETWEEN 0 AND 100),
  CONSTRAINT `FK_GPU_MODEL_BENCHMARK_GPU_MODEL_ID` FOREIGN KEY (`TENANT_ID`, `GPU_MODEL_ID`) REFERENCES `GPU_MODEL` (`TENANT_ID`, `GPU_MODEL_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Reference burn-in figures per GPU model; a node below HELD_BACK_BELOW_PCT of the reference is held back from sale (BRULE-GPU-22).';

-- POWER_RATE_CARD: Geography-wide power price defaults used when a site has no contract figure (demand charge, colocation rate, overage multiplier).
-- Related tables: POWER_RATE_CARD → GEOGRAPHY
-- Domain: A. Configuration and reference data · Updated: 2026-11-12
CREATE TABLE `POWER_RATE_CARD` (
  `POWER_RATE_CARD_ID` SMALLINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of POWER_RATE_CARD',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `GEOGRAPHY_ID` SMALLINT UNSIGNED NOT NULL COMMENT 'Geography',
  `CURRENCY_CODE` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Currency of the rates',
  `DEFAULT_ENERGY_RATE` DECIMAL(12,5) NOT NULL COMMENT 'Default energy price per kWh',
  `DEFAULT_SUPPLIER` VARCHAR(200) NOT NULL COMMENT 'Supplier name used with the default price',
  `DEMAND_CHARGE_RATE` DECIMAL(12,5) NOT NULL COMMENT 'Utility demand charge per kW (kVA) per month',
  `COLO_BLOCK_RATE` DECIMAL(12,5) NOT NULL COMMENT 'Colocation all-in rate per committed kW per month',
  `OVERAGE_MULTIPLIER` DECIMAL(5,2) NOT NULL DEFAULT 1.50 COMMENT 'Price multiple on draw above a colocation block',
  `PEAK_OVER_MEAN_FACTOR` DECIMAL(5,3) NOT NULL DEFAULT 1.060 COMMENT 'Factor on the prior 12-month peak before a new demand peak is a finding',
  `TARIFF_SOURCE` VARCHAR(200) NOT NULL COMMENT 'Source of the energy prices',
  `DEMAND_SOURCE` VARCHAR(200) NOT NULL COMMENT 'Source of the demand charge',
  `COLO_SOURCE` VARCHAR(200) NOT NULL COMMENT 'Source of the colocation rate',
  `AS_OF` DATE NOT NULL COMMENT 'Date the rates apply from',
  `IS_ILLUSTRATIVE` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = illustrative figures, marked so on screen',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`POWER_RATE_CARD_ID`),
  UNIQUE KEY `UK_POWER_RATE_CARD_TENANT_ID_GEOGRAPHY_ID_AS_OF` (`TENANT_ID`, `GEOGRAPHY_ID`, `AS_OF`),
  CONSTRAINT `CK_POWER_RATE_CARD_01` CHECK (DEFAULT_ENERGY_RATE >= 0),
  CONSTRAINT `CK_POWER_RATE_CARD_02` CHECK (DEMAND_CHARGE_RATE >= 0),
  CONSTRAINT `CK_POWER_RATE_CARD_03` CHECK (COLO_BLOCK_RATE >= 0),
  CONSTRAINT `CK_POWER_RATE_CARD_04` CHECK (OVERAGE_MULTIPLIER >= 1),
  CONSTRAINT `CK_POWER_RATE_CARD_05` CHECK (PEAK_OVER_MEAN_FACTOR >= 1),
  CONSTRAINT `FK_POWER_RATE_CARD_GEOGRAPHY_ID` FOREIGN KEY (`TENANT_ID`, `GEOGRAPHY_ID`) REFERENCES `GEOGRAPHY` (`TENANT_ID`, `GEOGRAPHY_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Geography-wide power price defaults used when a site has no contract figure (demand charge, colocation rate, overage multiplier).';

-- POWER_TARIFF: Energy tariff per state / region (BRD DATA-006); a site uses the tariff of its state unless its contract sets a price.
-- Related tables: POWER_TARIFF → GEOGRAPHY_REGION
-- Domain: A. Configuration and reference data · Updated: 2026-11-12
CREATE TABLE `POWER_TARIFF` (
