  `GEOGRAPHY_REGION_ID` INT UNSIGNED NOT NULL COMMENT 'State or region the tariff applies to',
  `CURRENCY_CODE` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Currency of the price',
  `ENERGY_RATE` DECIMAL(12,5) NOT NULL COMMENT 'Energy price per kWh',
  `SUPPLIER` VARCHAR(200) NOT NULL COMMENT 'Utility / DISCOM',
  `SOURCE` VARCHAR(200) NOT NULL COMMENT 'Source (e.g. EIA industrial average)',
  `AS_OF` DATE NOT NULL COMMENT 'Date the price applies from',
  `IS_ILLUSTRATIVE` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = illustrative, replaced by the customer''s tariff sheet',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`POWER_TARIFF_ID`),
  UNIQUE KEY `UK_POWER_TARIFF_TENANT_ID_GEOGRAPHY_REGION_ID_AS_OF` (`TENANT_ID`, `GEOGRAPHY_REGION_ID`, `AS_OF`),
  CONSTRAINT `CK_POWER_TARIFF_01` CHECK (ENERGY_RATE >= 0),
  CONSTRAINT `FK_POWER_TARIFF_GEOGRAPHY_REGION_ID` FOREIGN KEY (`TENANT_ID`, `GEOGRAPHY_REGION_ID`) REFERENCES `GEOGRAPHY_REGION` (`TENANT_ID`, `GEOGRAPHY_REGION_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Energy tariff per state / region (BRD DATA-006); a site uses the tariff of its state unless its contract sets a price.';

-- POWER_CONTRACT: Power supply contract of a site: utility connection with take-or-pay floor and demand charge, or a colocation power block (BRD 7.8).
-- Related tables: POWER_CONTRACT ← POWER_FINDING
-- Domain: A. Configuration and reference data · Updated: 2026-11-12
CREATE TABLE `POWER_CONTRACT` (
  `POWER_CONTRACT_ID` INT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of POWER_CONTRACT',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `INV_SITE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Datacenter (site) id in Plan to Build Inventory; row access follows the user''s site scope',
  `CONTRACT_KIND` ENUM('utility','colocation') NOT NULL COMMENT 'utility = connection + demand charge; colocation = committed block',
  `SUPPLIER` VARCHAR(200) NOT NULL COMMENT 'Utility or colocation provider',
  `CONTRACT_REF` VARCHAR(50) NULL COMMENT 'Supplier contract reference',
  `CURRENCY_CODE` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Currency of the rates',
  `ENERGY_RATE` DECIMAL(12,5) NULL COMMENT 'Contract energy price per kWh; NULL = the state tariff applies',
  `CAPACITY_RATE` DECIMAL(12,5) NOT NULL COMMENT 'Utility: demand charge per kW-month; colocation: all-in rate per committed kW-month',
  `COMMITTED_KW` DECIMAL(12,3) NOT NULL COMMENT 'Utility connection size or colocation block, kW',
  `FLOOR_PCT` DECIMAL(5,2) NOT NULL COMMENT 'Take-or-pay floor as a share of COMMITTED_KW (colocation = 100)',
  `ESCALATOR_PCT` DECIMAL(5,2) NOT NULL DEFAULT 0.00 COMMENT 'Yearly price escalator',
  `TERM_START` DATE NOT NULL COMMENT 'Contract start',
  `TERM_END` DATE NOT NULL COMMENT 'Contract end',
  `IS_ILLUSTRATIVE` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = seeded illustrative contract',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`POWER_CONTRACT_ID`),
  UNIQUE KEY `UK_POWER_CONTRACT_TENANT_ID_INV_SITE_ID_TERM_START` (`TENANT_ID`, `INV_SITE_ID`, `TERM_START`),
  UNIQUE KEY `UK_POWER_CONTRACT_TENANT_ID_POWER_CONTRACT_ID` (`TENANT_ID`, `POWER_CONTRACT_ID`),
  CONSTRAINT `CK_POWER_CONTRACT_01` CHECK (TERM_START < TERM_END),
  CONSTRAINT `CK_POWER_CONTRACT_02` CHECK (COMMITTED_KW > 0),
  CONSTRAINT `CK_POWER_CONTRACT_03` CHECK (CAPACITY_RATE >= 0),
  CONSTRAINT `CK_POWER_CONTRACT_04` CHECK (CONTRACT_KIND = 'utility' OR FLOOR_PCT = 100),
  CONSTRAINT `CK_POWER_CONTRACT_05` CHECK (ENERGY_RATE >= 0),
  CONSTRAINT `CK_POWER_CONTRACT_06` CHECK (ESCALATOR_PCT BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Power supply contract of a site: utility connection with take-or-pay floor and demand charge, or a colocation power block (BRD 7.8).';

-- METRIC_DEFINITION: Metric catalogue sent to the OAP telemetry ingestion service (INTG-057): name, unit, labels and expected interval per source.
-- Domain: A. Configuration and reference data · Updated: 2026-11-12
CREATE TABLE `METRIC_DEFINITION` (
  `METRIC_DEFINITION_ID` INT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of METRIC_DEFINITION',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `METRIC_NAME` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Metric name as stored in OAP (e.g. DCGM_FI_DEV_POWER_USAGE)',
  `LABEL` VARCHAR(200) NOT NULL COMMENT 'Display name',
  `UNIT` VARCHAR(24) NOT NULL COMMENT 'Unit (W, °C, %, kWh ...)',
  `METRIC_DOMAIN` ENUM('power','cooling','environment','network','compute','gpu','storage','security') NOT NULL COMMENT 'Domain the metric belongs to',
  `SOURCE_KIND` ENUM('snmp','modbus','bacnet','redfish','dcgm','habana','xpu','gnmi','syslog','bms','pacs','other') NOT NULL COMMENT 'Protocol / exporter that delivers it',
  `EXPECTED_INTERVAL_S` INT UNSIGNED NOT NULL COMMENT 'Expected sampling interval, seconds; stale after 3 intervals',
  `LABEL_KEYS` VARCHAR(500) NULL COMMENT 'Label keys the series carries, as documentation for OAP (not parsed by SynapseDC)',
  `DESCRIPTION` VARCHAR(2000) NULL COMMENT 'Meaning of the metric',
  `IS_ACTIVE` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = collected',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`METRIC_DEFINITION_ID`),
  UNIQUE KEY `UK_METRIC_DEFINITION_TENANT_ID_METRIC_NAME` (`TENANT_ID`, `METRIC_NAME`),
  CONSTRAINT `CK_METRIC_DEFINITION_01` CHECK (EXPECTED_INTERVAL_S > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Metric catalogue sent to the OAP telemetry ingestion service (INTG-057): name, unit, labels and expected interval per source.';

-- DCIM_WORK_ITEM: A DCIM edit saved under a change request that is not approved yet. Executing it writes to Inventory / Inventory Planning (W-18…21, W-38) and marks it Done (BRD 7.10, OD-01).
-- Related tables: DCIM_WORK_ITEM ← DCIM_WORK_ITEM_TARGET, WRITEBACK_REQUEST
-- Domain: B. DCIM work waiting for approval · Updated: 2026-11-12
CREATE TABLE `DCIM_WORK_ITEM` (
  `DCIM_WORK_ITEM_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of DCIM_WORK_ITEM',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `INV_SITE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Datacenter (site) id in Plan to Build Inventory; row access follows the user''s site scope',
  `WORK_ITEM_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Business code, e.g. DWI-000123',
  `ITSM_CHANGE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Change request id in ITSM Change management',
  `CR_MODE` ENUM('standard','existing','raised') NOT NULL COMMENT 'How the change request was chosen: standard pre-approved, an open CR, or raised for this edit',
  `OPERATION` ENUM('createRack','installDevice','setDeviceStatus','connect','disconnect','editInterface','installModule','removeModule','swapModule','editRack','retireRack','moveDevice','reserveU','releaseU','createPanel','createFeed') NOT NULL COMMENT 'DCIM operation to replay against the Inventory write API',
  `LABEL` VARCHAR(200) NOT NULL COMMENT 'What the edit does, in words',
  `INV_HALL_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Hall (room) id in Inventory, when the edit is in a hall',
  `INV_RACK_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Rack id in Inventory, when the edit is on a rack',
  `INV_DEVICE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Device id in Inventory, when the edit is on a device',
  `ARGUMENTS` JSON NOT NULL COMMENT 'Arguments of the operation exactly as the write API takes them (replayed on execution)',
  `STATUS` ENUM('Planned','Done','Failed','Cancelled') NOT NULL DEFAULT 'Planned' COMMENT 'Planned until executed',
  `EXECUTED_AT` DATETIME(3) NULL COMMENT 'When it was executed',
  `EXECUTED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Who executed it',
  `RESULT_MESSAGE` VARCHAR(1000) NULL COMMENT 'Result returned by the write API',
  `ERROR_MESSAGE` VARCHAR(1000) NULL COMMENT 'Error when STATUS = Failed',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`DCIM_WORK_ITEM_ID`),
  UNIQUE KEY `UK_DCIM_WORK_ITEM_TENANT_ID_WORK_ITEM_CODE` (`TENANT_ID`, `WORK_ITEM_CODE`),
  UNIQUE KEY `UK_DCIM_WORK_ITEM_TENANT_ID_DCIM_WORK_ITEM_ID` (`TENANT_ID`, `DCIM_WORK_ITEM_ID`),
  KEY `IDX_DCIM_WORK_ITEM_TENANT_ID_ITSM_CHANGE_ID` (`TENANT_ID`, `ITSM_CHANGE_ID`),
  KEY `IDX_DCIM_WORK_ITEM_TENANT_ID_INV_SITE_ID_STATUS` (`TENANT_ID`, `INV_SITE_ID`, `STATUS`),
  KEY `IDX_DCIM_WORK_ITEM_TENANT_ID_STATUS` (`TENANT_ID`, `STATUS`),
  KEY `IDX_DCIM_WORK_ITEM_INV_RACK_ID` (`INV_RACK_ID`),
  KEY `IDX_DCIM_WORK_ITEM_INV_DEVICE_ID` (`INV_DEVICE_ID`),
  CONSTRAINT `CK_DCIM_WORK_ITEM_01` CHECK (STATUS <> 'Done' OR EXECUTED_AT IS NOT NULL),
  CONSTRAINT `CK_DCIM_WORK_ITEM_02` CHECK (STATUS <> 'Failed' OR ERROR_MESSAGE IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='A DCIM edit saved under a change request that is not approved yet. Executing it writes to Inventory / Inventory Planning (W-18…21, W-38) and marks it Done (BRD 7.10, OD-01).';

