-- ALARM_TAG: SynapseDC tags on a System Alerts alarm: scope against the site, placement and correlation. Used only while System Alerts cannot store these tags.
-- Domain: C. Operations enrichment · Updated: 2026-11-12
CREATE TABLE `ALARM_TAG` (
  `ALARM_TAG_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of ALARM_TAG',
