  `FAULT_LOCATION` VARCHAR(200) NULL COMMENT 'Where that fault is',
  `SYMPTOM_OF_ALARM_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Alarm id (System Alerts) this alarm is a symptom of',
  `TAGGED_AT` DATETIME(3) NOT NULL COMMENT 'When SynapseDC tagged it',
