  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`ALARM_TAG_ID`),
  UNIQUE KEY `UK_ALARM_TAG_TENANT_ID_ALR_ALARM_ID` (`TENANT_ID`, `ALR_ALARM_ID`),
  KEY `IDX_ALARM_TAG_TENANT_ID_INV_SITE_ID_SCOPE` (`TENANT_ID`, `INV_SITE_ID`, `SCOPE`),
  KEY `IDX_ALARM_TAG_TENANT_ID_CORRELATION_KEY` (`TENANT_ID`, `CORRELATION_KEY`),
  KEY `IDX_ALARM_TAG_SYMPTOM_OF_ALARM_ID` (`SYMPTOM_OF_ALARM_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='SynapseDC tags on a System Alerts alarm: scope against the site, placement and correlation. Used only while System Alerts cannot store these tags.';

-- INCIDENT_ENRICHMENT: SynapseDC additions to an ITSM incident: impact and money snapshots, RCA feedback. Used only where ITSM has no extension fields (W-05, W-07).
-- Related tables: INCIDENT_ENRICHMENT ← INCIDENT_IMPACT_ITEM, INCIDENT_RCA_HYPOTHESIS, INCIDENT_ACTION_STEP, INCIDENT_VERIFICATION_CHECK
-- Domain: C. Operations enrichment · Updated: 2026-11-12
CREATE TABLE `INCIDENT_ENRICHMENT` (
  `INCIDENT_ENRICHMENT_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of INCIDENT_ENRICHMENT',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `INV_SITE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Datacenter (site) id in Plan to Build Inventory; row access follows the user''s site scope',
  `ITSM_INCIDENT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Incident id in ITSM',
  `IMPACT_LEVEL` ENUM('Low','Medium','High') NOT NULL COMMENT 'Impact level at the last snapshot',
  `IMPACTED_SERVICES` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Services impacted at the last snapshot',
  `IMPACTED_CUSTOMERS` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Customers impacted at the last snapshot',
  `PREMIUM_CUSTOMERS` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Premium customers impacted at the last snapshot',
  `CURRENCY_CODE` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Currency of the money columns',
  `REVENUE_AT_RISK` DECIMAL(16,2) NOT NULL DEFAULT 0.00 COMMENT 'Money at risk at the last snapshot',
  `IMPACT_SUMMARY` VARCHAR(1000) NULL COMMENT 'Impact in one sentence',
  `IMPACT_SNAPSHOT_AT` DATETIME(3) NOT NULL COMMENT 'When the impact snapshot was taken (DATA-022)',
  `MONEY_LOST_AT_CLOSE` DECIMAL(16,2) NULL COMMENT 'Money lost, frozen when the incident closed',
  `CREDITS_AT_CLOSE` DECIMAL(16,2) NULL COMMENT 'SLA credits caused, frozen when the incident closed',
  `CLOSED_SNAPSHOT_AT` DATETIME(3) NULL COMMENT 'When the close snapshot was taken',
  `RCA_FEEDBACK` ENUM('confirmed','rejected') NULL COMMENT 'Engineer verdict on the leading hypothesis',
  `FEEDBACK_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Who gave the verdict',
  `FEEDBACK_AT` DATETIME(3) NULL COMMENT 'When',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`INCIDENT_ENRICHMENT_ID`),
  UNIQUE KEY `UK_INCIDENT_ENRICHMENT_TENANT_ID_ITSM_INCIDENT_ID` (`TENANT_ID`, `ITSM_INCIDENT_ID`),
  UNIQUE KEY `UK_INCIDENT_ENRICHMENT_TENANT_ID_INCIDENT_ENRICHMENT_ID` (`TENANT_ID`, `INCIDENT_ENRICHMENT_ID`),
  KEY `IDX_INCIDENT_ENRICHMENT_TENANT_ID_INV_SITE_ID` (`TENANT_ID`, `INV_SITE_ID`),
  CONSTRAINT `CK_INCIDENT_ENRICHMENT_01` CHECK (REVENUE_AT_RISK >= 0),
  CONSTRAINT `CK_INCIDENT_ENRICHMENT_02` CHECK (MONEY_LOST_AT_CLOSE IS NULL OR MONEY_LOST_AT_CLOSE >= 0),
  CONSTRAINT `CK_INCIDENT_ENRICHMENT_03` CHECK (CREDITS_AT_CLOSE IS NULL OR CREDITS_AT_CLOSE >= 0),
  CONSTRAINT `CK_INCIDENT_ENRICHMENT_04` CHECK ((MONEY_LOST_AT_CLOSE IS NULL) = (CLOSED_SNAPSHOT_AT IS NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='SynapseDC additions to an ITSM incident: impact and money snapshots, RCA feedback. Used only where ITSM has no extension fields (W-05, W-07).';

