-- INCIDENT_RCA_HYPOTHESIS: Root-cause hypothesis proposed for an incident, ranked, with confidence.
-- Related tables: INCIDENT_RCA_HYPOTHESIS ← INCIDENT_RCA_EVIDENCE
-- Domain: C. Operations enrichment · Updated: 2026-11-12
CREATE TABLE `INCIDENT_RCA_HYPOTHESIS` (
  `INCIDENT_RCA_HYPOTHESIS_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of INCIDENT_RCA_HYPOTHESIS',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `INCIDENT_ENRICHMENT_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Incident enrichment',
  `RANK_NO` TINYINT UNSIGNED NOT NULL COMMENT 'Rank, 1 = leading',
  `CAUSE` VARCHAR(1000) NOT NULL COMMENT 'Proposed cause',
  `CONFIDENCE_PCT` DECIMAL(5,2) NOT NULL COMMENT 'Confidence, %',
  `IS_REJECTED` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = rejected by the engineer',
  `ITSM_CHANGE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Change the hypothesis blames (counts that change as failed)',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`INCIDENT_RCA_HYPOTHESIS_ID`),
  UNIQUE KEY `UK_IRH_TENANT_ID_IE_ID_RANK_NO` (`TENANT_ID`, `INCIDENT_ENRICHMENT_ID`, `RANK_NO`),
  UNIQUE KEY `UK_INCIDENT_RCA_HYPOTHESIS_TENANT_ID_INCIDENT_RCA_HYPOTHESIS_ID` (`TENANT_ID`, `INCIDENT_RCA_HYPOTHESIS_ID`),
  KEY `IDX_INCIDENT_RCA_HYPOTHESIS_ITSM_CHANGE_ID` (`ITSM_CHANGE_ID`),
  CONSTRAINT `CK_INCIDENT_RCA_HYPOTHESIS_01` CHECK (CONFIDENCE_PCT BETWEEN 0 AND 100),
  CONSTRAINT `FK_INCIDENT_RCA_HYPOTHESIS_INCIDENT_ENRICHMENT_ID` FOREIGN KEY (`TENANT_ID`, `INCIDENT_ENRICHMENT_ID`) REFERENCES `INCIDENT_ENRICHMENT` (`TENANT_ID`, `INCIDENT_ENRICHMENT_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Root-cause hypothesis proposed for an incident, ranked, with confidence.';

