-- POWER_FINDING: Power contract finding per site (block near limit, demand ratchet, unexplained rise, idle block) and the alarm / incident raised for it; de-duplicates the scheduled evaluation (DEV-08).
-- Related tables: POWER_FINDING → POWER_CONTRACT
-- Domain: C. Operations enrichment · Updated: 2026-11-12
CREATE TABLE `POWER_FINDING` (
  `POWER_FINDING_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of POWER_FINDING',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `INV_SITE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Datacenter (site) id in Plan to Build Inventory; row access follows the user''s site scope',
  `POWER_CONTRACT_ID` INT UNSIGNED NULL COMMENT 'Contract the finding is against',
  `FINDING_KIND` ENUM('block-near-limit','demand-ratchet','unexplained-rise','idle-block') NOT NULL COMMENT 'Kind of finding',
  `ALARM_SEVERITY` ENUM('major','minor','warning') NOT NULL COMMENT 'Severity of the raised alarm',
  `TITLE` VARCHAR(200) NOT NULL COMMENT 'Title',
  `DETAIL` VARCHAR(2000) NOT NULL COMMENT 'What was found',
  `CURRENCY_CODE` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Currency of the exposure',
  `EXPOSURE_AMOUNT` DECIMAL(16,2) NOT NULL COMMENT 'Money exposure (per year)',
  `EXPOSURE_LABEL` VARCHAR(100) NOT NULL COMMENT 'How the exposure reads on screen',
  `EVIDENCE_SNAPSHOT` JSON NULL COMMENT 'Snapshot of the figures behind the finding: [{label, value}] (DATA-022)',
  `FIRST_SEEN_AT` DATETIME(3) NOT NULL COMMENT 'First evaluation that found it',
  `LAST_SEEN_AT` DATETIME(3) NOT NULL COMMENT 'Latest evaluation that still found it',
  `STATUS` ENUM('Open','Resolved','Dismissed') NOT NULL DEFAULT 'Open' COMMENT 'Open until an evaluation no longer finds it',
  `ALR_ALARM_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Alarm raised in System Alerts',
  `ITSM_INCIDENT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Incident raised in ITSM (costliest block / ratchet finding)',
  `OPEN_FINDING_KEY` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF(STATUS = 'Open', CONCAT(INV_SITE_ID, '|', FINDING_KIND), NULL)) STORED NULL COMMENT 'One open finding per site and kind (generated)',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`POWER_FINDING_ID`),
  UNIQUE KEY `UK_POWER_FINDING_TENANT_ID_OPEN_FINDING_KEY` (`TENANT_ID`, `OPEN_FINDING_KEY`),
  KEY `IDX_POWER_FINDING_TENANT_ID_INV_SITE_ID_STATUS` (`TENANT_ID`, `INV_SITE_ID`, `STATUS`),
  KEY `IDX_POWER_FINDING_TENANT_ID_STATUS` (`TENANT_ID`, `STATUS`),
  KEY `IDX_POWER_FINDING_TENANT_ID_POWER_CONTRACT_ID` (`TENANT_ID`, `POWER_CONTRACT_ID`),
  KEY `IDX_POWER_FINDING_ALR_ALARM_ID` (`ALR_ALARM_ID`),
  CONSTRAINT `CK_POWER_FINDING_01` CHECK (EXPOSURE_AMOUNT >= 0),
  CONSTRAINT `CK_POWER_FINDING_02` CHECK (FIRST_SEEN_AT <= LAST_SEEN_AT),
  CONSTRAINT `FK_POWER_FINDING_POWER_CONTRACT_ID` FOREIGN KEY (`TENANT_ID`, `POWER_CONTRACT_ID`) REFERENCES `POWER_CONTRACT` (`TENANT_ID`, `POWER_CONTRACT_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Power contract finding per site (block near limit, demand ratchet, unexplained rise, idle block) and the alarm / incident raised for it; de-duplicates the scheduled evaluation (DEV-08).';

-- PLAN_TEMPLATE: Identity of a planner template (plan type, site type profile, module, rule set, checklist, document). Content lives in PLAN_TEMPLATE_VERSION; published versions never change (DATA-020).
