  UNIQUE KEY `UK_PLAN_TEMPLATE_TENANT_ID_TEMPLATE_CODE` (`TENANT_ID`, `TEMPLATE_CODE`),
  UNIQUE KEY `UK_PLAN_TEMPLATE_TENANT_ID_PLAN_TEMPLATE_ID` (`TENANT_ID`, `PLAN_TEMPLATE_ID`),
  KEY `IDX_PLAN_TEMPLATE_TENANT_ID_TEMPLATE_KIND` (`TENANT_ID`, `TEMPLATE_KIND`),
  CONSTRAINT `CK_PLAN_TEMPLATE_01` CHECK ((RETIRED_AT IS NULL) = (RETIRED_BY IS NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Identity of a planner template (plan type, site type profile, module, rule set, checklist, document). Content lives in PLAN_TEMPLATE_VERSION; published versions never change (DATA-020).';

-- PLAN_TEMPLATE_VERSION: One version of a template. Draft → Awaiting approval → Published → Superseded; one draft and one published version per template at a time.
-- Related tables: PLAN_TEMPLATE_VERSION → PLAN_TEMPLATE; ← PLAN_TEMPLATE_INPUT, PLAN_TEMPLATE_RULE, PLAN_TEMPLATE_ASPECT, PLAN_TEMPLATE_APPROVAL_STEP, PLAN_TEMPLATE_OUTPUT, PLAN_TEMPLATE_ITEM, PLAN_TEMPLATE_LABEL, PLAN_TEMPLATE_MODULE, PLAN_TEMPLATE_DEMAND_PHASE, PLAN_SITE_TYPE
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_TEMPLATE_VERSION` (
  `PLAN_TEMPLATE_VERSION_ID` INT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_TEMPLATE_VERSION',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_TEMPLATE_ID` INT UNSIGNED NOT NULL COMMENT 'Template',
