  `NAME` VARCHAR(200) NOT NULL COMMENT 'Template name',
  `DESCRIPTION` VARCHAR(2000) NULL COMMENT 'What it is for',
  `OWNER_NAME` VARCHAR(200) NOT NULL COMMENT 'Owning team or person',
  `PLAN_SCOPE` ENUM('rack','pod','hall','retrofit','plant','network','expansion','new-dc','portfolio','migration','edge','server-refresh','network-refresh','rack-replace') NULL COMMENT 'Plan family (plan types only)',
  `DC_TYPE_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Site type key the template is for (built-in key or custom-…)',
  `INHERITS_FROM_TEMPLATE_ID` INT UNSIGNED NULL COMMENT 'Parent template it inherits from (variant); NULL = root',
  `APPLIES_TO_LEVEL` ENUM('org','region','site') NOT NULL DEFAULT 'org' COMMENT 'Where it may be used',
  `APPLIES_TO_REF_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Region code or Inventory site id when APPLIES_TO_LEVEL is not org',
  `APPLIES_TO_LABEL` VARCHAR(200) NULL COMMENT 'Display name of the region / site',
  `EXECUTES_AS` ENUM('change','project','programme','portfolio') NULL COMMENT 'Delivery vehicle created when a plan on it starts',
  `BLUEPRINT_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Delivery blueprint used for the build',
  `ATP_SYSTEM` ENUM('Power','Cooling','Network','Controls','Integrated') NULL COMMENT 'Checklists: commissioning system it tests; NULL = gate list',
  `IS_PER_SITE` TINYINT(1) NOT NULL DEFAULT 0 COMMENT 'Checklists: 1 = one test per site (edge acceptance)',
  `DEMAND_GPU_PCT` DECIMAL(5,2) NULL COMMENT 'Demand profile: GPU share of the workload mix',
  `DEMAND_COMPUTE_PCT` DECIMAL(5,2) NULL COMMENT 'Demand profile: compute share',
  `DEMAND_STORAGE_PCT` DECIMAL(5,2) NULL COMMENT 'Demand profile: storage share',
  `CHANGE_NOTE` VARCHAR(1000) NULL COMMENT 'Note on what changed in this version',
  `PUBLISH_REQUESTED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Who asked to publish (versions of a template in use need approval)',
  `PUBLISH_REQUESTED_AT` DATETIME(3) NULL COMMENT 'When publication was requested',
  `PUBLISH_REASON` VARCHAR(1000) NULL COMMENT 'Reason given with the request',
  `DECIDED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Approver who published or rejected (not the requester)',
  `DECIDED_AT` DATETIME(3) NULL COMMENT 'When the request was decided',
  `DECISION_REASON` VARCHAR(1000) NULL COMMENT 'Reason given by the approver',
  `PUBLISHED_AT` DATETIME(3) NULL COMMENT 'When this version became live',
  `PUBLISHED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Who published it',
  `OPEN_DRAFT_KEY` INT UNSIGNED GENERATED ALWAYS AS (IF(VERSION_STATUS IN ('Draft','Awaiting approval'), PLAN_TEMPLATE_ID, NULL)) STORED NULL COMMENT 'One open draft per template (generated)',
  `LIVE_KEY` INT UNSIGNED GENERATED ALWAYS AS (IF(VERSION_STATUS = 'Published', PLAN_TEMPLATE_ID, NULL)) STORED NULL COMMENT 'One published version per template (generated)',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_TEMPLATE_VERSION_ID`),
  UNIQUE KEY `UK_PLAN_TEMPLATE_VERSION_TENANT_ID_PLAN_TEMPLATE_ID_VERSION_NO` (`TENANT_ID`, `PLAN_TEMPLATE_ID`, `VERSION_NO`),
  UNIQUE KEY `UK_PLAN_TEMPLATE_VERSION_OPEN_DRAFT_KEY` (`OPEN_DRAFT_KEY`),
  UNIQUE KEY `UK_PLAN_TEMPLATE_VERSION_LIVE_KEY` (`LIVE_KEY`),
  UNIQUE KEY `UK_PLAN_TEMPLATE_VERSION_TENANT_ID_PLAN_TEMPLATE_VERSION_ID` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`),
  KEY `IDX_PLAN_TEMPLATE_VERSION_TENANT_ID_INHERITS_FROM_TEMPLATE_ID` (`TENANT_ID`, `INHERITS_FROM_TEMPLATE_ID`),
  KEY `IDX_PLAN_TEMPLATE_VERSION_TENANT_ID_VERSION_STATUS` (`TENANT_ID`, `VERSION_STATUS`),
  CONSTRAINT `CK_PLAN_TEMPLATE_VERSION_01` CHECK (VERSION_NO > 0),
  CONSTRAINT `CK_PLAN_TEMPLATE_VERSION_02` CHECK (DEMAND_GPU_PCT IS NULL OR DEMAND_GPU_PCT + DEMAND_COMPUTE_PCT + DEMAND_STORAGE_PCT = 100),
  CONSTRAINT `CK_PLAN_TEMPLATE_VERSION_03` CHECK (VERSION_STATUS <> 'Published' OR PUBLISHED_AT IS NOT NULL),
  CONSTRAINT `CK_PLAN_TEMPLATE_VERSION_04` CHECK (VERSION_STATUS <> 'Awaiting approval' OR PUBLISH_REQUESTED_BY IS NOT NULL),
  CONSTRAINT `CK_PLAN_TEMPLATE_VERSION_05` CHECK (DECIDED_BY IS NULL OR PUBLISH_REQUESTED_BY IS NULL OR DECIDED_BY <> PUBLISH_REQUESTED_BY),
  CONSTRAINT `FK_PLAN_TEMPLATE_VERSION_PLAN_TEMPLATE_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_TEMPLATE_ID`) REFERENCES `PLAN_TEMPLATE` (`TENANT_ID`, `PLAN_TEMPLATE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_TEMPLATE_VERSION_INHERITS_FROM_TEMPLATE_ID` FOREIGN KEY (`TENANT_ID`, `INHERITS_FROM_TEMPLATE_ID`) REFERENCES `PLAN_TEMPLATE` (`TENANT_ID`, `PLAN_TEMPLATE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='One version of a template. Draft → Awaiting approval → Published → Superseded; one draft and one published version per template at a time.';

