-- PLAN_TEMPLATE_INPUT: Input (parameter) a template version defines or overrides: default and allowed range or options.
-- Related tables: PLAN_TEMPLATE_INPUT ← PLAN_TEMPLATE_INPUT_OPTION
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_TEMPLATE_INPUT` (
  `PLAN_TEMPLATE_INPUT_ID` INT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_TEMPLATE_INPUT',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_TEMPLATE_VERSION_ID` INT UNSIGNED NOT NULL COMMENT 'Template version',
  `INPUT_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Input key the planner engine reads (from the input catalogue)',
  `LABEL` VARCHAR(200) NOT NULL COMMENT 'Display name',
  `ASPECT` ENUM('space','power','cooling','network','it','fire','security','sustainability','resilience','operations','supply','schedule','finance','compliance','commissioning','migration','risk') NOT NULL COMMENT 'Wizard area the input belongs to',
  `INPUT_TYPE` ENUM('number','text','select','bool') NOT NULL COMMENT 'Type of value',
  `UNIT` VARCHAR(24) NULL COMMENT 'Unit',
  `DEFAULT_NUMBER` DECIMAL(20,6) NULL COMMENT 'Default when INPUT_TYPE = number',
  `DEFAULT_TEXT` VARCHAR(255) NULL COMMENT 'Default when INPUT_TYPE = text or select',
  `DEFAULT_BOOL` TINYINT(1) NULL COMMENT 'Default when INPUT_TYPE = bool',
  `MIN_VALUE` DECIMAL(20,6) NULL COMMENT 'Lowest allowed value (numbers)',
  `MAX_VALUE` DECIMAL(20,6) NULL COMMENT 'Highest allowed value (numbers)',
  `HELP_TEXT` VARCHAR(1000) NULL COMMENT 'Help shown under the input',
  `IS_DERIVED` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = computed by the planner, not typed by the user',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_TEMPLATE_INPUT_ID`),
  UNIQUE KEY `UK_PTI_TENANT_ID_PTV_ID_INPUT_KEY` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`, `INPUT_KEY`),
  UNIQUE KEY `UK_PLAN_TEMPLATE_INPUT_TENANT_ID_PLAN_TEMPLATE_INPUT_ID` (`TENANT_ID`, `PLAN_TEMPLATE_INPUT_ID`),
  CONSTRAINT `CK_PLAN_TEMPLATE_INPUT_01` CHECK (MIN_VALUE IS NULL OR MAX_VALUE IS NULL OR MIN_VALUE <= MAX_VALUE),
  CONSTRAINT `CK_PLAN_TEMPLATE_INPUT_02` CHECK (INPUT_TYPE = 'number' OR (DEFAULT_NUMBER IS NULL AND MIN_VALUE IS NULL AND MAX_VALUE IS NULL)),
  CONSTRAINT `CK_PLAN_TEMPLATE_INPUT_03` CHECK (INPUT_TYPE = 'bool' OR DEFAULT_BOOL IS NULL),
  CONSTRAINT `CK_PLAN_TEMPLATE_INPUT_04` CHECK (INPUT_TYPE IN ('text','select') OR DEFAULT_TEXT IS NULL),
  CONSTRAINT `FK_PLAN_TEMPLATE_INPUT_PLAN_TEMPLATE_VERSION_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) REFERENCES `PLAN_TEMPLATE_VERSION` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Input (parameter) a template version defines or overrides: default and allowed range or options.';

