  KEY `IDX_PLAN_TEMPLATE_RULE_TENANT_ID_RULE_CODE` (`TENANT_ID`, `RULE_CODE`),
  CONSTRAINT `FK_PLAN_TEMPLATE_RULE_PLAN_TEMPLATE_VERSION_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) REFERENCES `PLAN_TEMPLATE_VERSION` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Rule a template version checks: an engine check with its own settings; IS_OFF switches an inherited rule off for this template and its variants.';

