  `SHARE_PCT` DECIMAL(5,2) NOT NULL COMMENT 'Share of the demand in this phase',
  `MONTHS_FROM_START` SMALLINT UNSIGNED NOT NULL COMMENT 'Months after the plan starts',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_TEMPLATE_DEMAND_PHASE_ID`),
  UNIQUE KEY `UK_PTDP_TENANT_ID_PTV_ID_SORT_ORDER` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`, `SORT_ORDER`),
  CONSTRAINT `CK_PLAN_TEMPLATE_DEMAND_PHASE_01` CHECK (SHARE_PCT BETWEEN 0 AND 100),
  CONSTRAINT `FK_PLAN_TEMPLATE_DEMAND_PHASE_PLAN_TEMPLATE_VERSION_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) REFERENCES `PLAN_TEMPLATE_VERSION` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Build phases of a demand profile: share of demand and months from start.';

-- PLAN_SITE_TYPE: Site type definition carried by a site-type profile version (custom site types; built-in types live in the application catalogue).
-- Related tables: PLAN_SITE_TYPE → PLAN_TEMPLATE_VERSION; ← PLAN_SITE_TYPE_COOLING_UNIT, PLAN_SITE_TYPE_GAP
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_SITE_TYPE` (
  `PLAN_SITE_TYPE_ID` INT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_SITE_TYPE',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_TEMPLATE_VERSION_ID` INT UNSIGNED NOT NULL COMMENT 'Profile template version',
  `SITE_TYPE_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Key, custom-<slug>',
  `NAME` VARCHAR(200) NOT NULL COMMENT 'Name',
  `SHORT_LABEL` VARCHAR(50) NOT NULL COMMENT 'Short label',
  `SEGMENT` ENUM('Enterprise','Telco') NOT NULL COMMENT 'Segment',
  `DESCRIPTION` VARCHAR(2000) NULL COMMENT 'Description',
  `BASED_ON_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Built-in site type it was created from (benchmarks fall back to it)',
  `RACKS_MIN` INT UNSIGNED NOT NULL COMMENT 'Typical racks, low',
  `RACKS_MAX` INT UNSIGNED NULL COMMENT 'Typical racks, high; NULL = no upper bound',
  `POWER_KW_MIN` DECIMAL(12,3) NOT NULL COMMENT 'Typical IT power, low',
  `POWER_KW_MAX` DECIMAL(12,3) NULL COMMENT 'Typical IT power, high; NULL = no upper bound',
  `KW_PER_RACK_MIN` DECIMAL(12,3) NULL COMMENT 'Rack density, low',
  `KW_PER_RACK_MAX` DECIMAL(12,3) NULL COMMENT 'Rack density, high',
  `COOLING_APPROACH` VARCHAR(200) NOT NULL COMMENT 'Cooling approach',
  `REDUNDANCY` VARCHAR(50) NOT NULL COMMENT 'Power redundancy (N, N+1, 2N)',
  `DEFAULT_TIER` ENUM('Tier I','Tier II','Tier III','Tier IV') NOT NULL COMMENT 'Default tier',
  `IS_HIGH_DENSITY` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = high-density site',
  `HAS_DC_POWER_PLANT` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = -48 V DC plant',
  `IS_MULTI_TENANT` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = multi-tenant',
  `COVERAGE` ENUM('Full','Strong','Partial','Gap') NOT NULL COMMENT 'How well the planner covers this site type',
  `PUE_TARGET` DECIMAL(4,2) NOT NULL COMMENT 'Design PUE target',
  `SEED_RACKS` INT UNSIGNED NOT NULL COMMENT 'Racks used to seed a new plan',
  `CONTAINMENT` VARCHAR(50) NOT NULL COMMENT 'Aisle containment',
  `RACK_HEIGHT_U` TINYINT UNSIGNED NOT NULL COMMENT 'Rack height, U',
  `COOLING_ZONES` SMALLINT UNSIGNED NOT NULL COMMENT 'Cooling zones',
  `LIQUID_COOLING` ENUM('none','optional','standard') NOT NULL COMMENT 'Liquid cooling',
  `COOLING_OVERHEAD` DECIMAL(5,3) NOT NULL COMMENT 'Cooling overhead factor',
  `FEED_VOLTAGE` VARCHAR(50) NOT NULL COMMENT 'Feed voltage',
  `BACKUP_RUNTIME_MIN_LOW` SMALLINT UNSIGNED NOT NULL COMMENT 'UPS runtime, low, minutes',
  `BACKUP_RUNTIME_MIN_HIGH` SMALLINT UNSIGNED NOT NULL COMMENT 'UPS runtime, high, minutes',
  `BUILDINGS` TINYINT UNSIGNED NOT NULL COMMENT 'Buildings',
  `FLOORS_MIN` TINYINT UNSIGNED NOT NULL COMMENT 'Floors per building, low',
  `FLOORS_MAX` TINYINT UNSIGNED NOT NULL COMMENT 'Floors per building, high',
  `WAN_KIND` ENUM('edge','enterprise','colo','telco') NOT NULL COMMENT 'WAN design',
  `IS_DIVERSITY_EXPECTED` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = diverse routes expected',
  `CIRCUITS` TINYINT UNSIGNED NOT NULL COMMENT 'Expected WAN circuits',
  `BUILD_BLUEPRINT_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Delivery blueprint',
  `BUILD_DURATION_FACTOR` DECIMAL(5,2) NOT NULL COMMENT 'Build duration factor against the blueprint',
  `BUILD_DEFAULT_BUDGET_USD` DECIMAL(16,2) NOT NULL COMMENT 'Default budget, USD',
  `RACK_POWER_WARN_PCT` DECIMAL(5,2) NOT NULL COMMENT 'Rack power: warn at',
  `RACK_POWER_BLOCK_PCT` DECIMAL(5,2) NOT NULL COMMENT 'Rack power: block at',
  `COOLING_HEADROOM_MIN_PCT` DECIMAL(5,2) NOT NULL COMMENT 'Minimum cooling headroom',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_SITE_TYPE_ID`),
  UNIQUE KEY `UK_PLAN_SITE_TYPE_TENANT_ID_PLAN_TEMPLATE_VERSION_ID` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`),
  UNIQUE KEY `UK_PLAN_SITE_TYPE_TENANT_ID_PLAN_SITE_TYPE_ID` (`TENANT_ID`, `PLAN_SITE_TYPE_ID`),
  KEY `IDX_PLAN_SITE_TYPE_TENANT_ID_SITE_TYPE_KEY` (`TENANT_ID`, `SITE_TYPE_KEY`),
  CONSTRAINT `CK_PLAN_SITE_TYPE_01` CHECK (RACKS_MAX IS NULL OR RACKS_MIN <= RACKS_MAX),
  CONSTRAINT `CK_PLAN_SITE_TYPE_02` CHECK (POWER_KW_MAX IS NULL OR POWER_KW_MIN <= POWER_KW_MAX),
  CONSTRAINT `CK_PLAN_SITE_TYPE_03` CHECK (KW_PER_RACK_MIN IS NULL OR KW_PER_RACK_MAX IS NULL OR KW_PER_RACK_MIN <= KW_PER_RACK_MAX),
  CONSTRAINT `CK_PLAN_SITE_TYPE_04` CHECK (RACK_POWER_WARN_PCT < RACK_POWER_BLOCK_PCT),
  CONSTRAINT `CK_PLAN_SITE_TYPE_05` CHECK (BACKUP_RUNTIME_MIN_LOW <= BACKUP_RUNTIME_MIN_HIGH),
  CONSTRAINT `CK_PLAN_SITE_TYPE_06` CHECK (FLOORS_MIN <= FLOORS_MAX),
  CONSTRAINT `CK_PLAN_SITE_TYPE_07` CHECK (PUE_TARGET >= 1),
  CONSTRAINT `CK_PLAN_SITE_TYPE_08` CHECK (RACK_HEIGHT_U IN (42, 45, 48)),
  CONSTRAINT `CK_PLAN_SITE_TYPE_09` CHECK (SITE_TYPE_KEY LIKE 'custom-%'),
  CONSTRAINT `CK_PLAN_SITE_TYPE_10` CHECK (COOLING_OVERHEAD > 0),
  CONSTRAINT `CK_PLAN_SITE_TYPE_11` CHECK (BUILD_DURATION_FACTOR > 0),
  CONSTRAINT `CK_PLAN_SITE_TYPE_12` CHECK (BUILD_DEFAULT_BUDGET_USD >= 0),
  CONSTRAINT `CK_PLAN_SITE_TYPE_13` CHECK (COOLING_HEADROOM_MIN_PCT BETWEEN 0 AND 100),
  CONSTRAINT `FK_PLAN_SITE_TYPE_PLAN_TEMPLATE_VERSION_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) REFERENCES `PLAN_TEMPLATE_VERSION` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Site type definition carried by a site-type profile version (custom site types; built-in types live in the application catalogue).';

