-- BENCHMARK_MEASURE: Measures a benchmark value can be given for; the measure fixes the unit, the tab and which applies-to fields matter.
-- Related tables: BENCHMARK_MEASURE ← BENCHMARK
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `BENCHMARK_MEASURE` (
  `BENCHMARK_MEASURE_ID` SMALLINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of BENCHMARK_MEASURE',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `MEASURE_CODE` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Measure key the engine reads (capex, pue, leadWeeks:<item> ...)',
  `LABEL` VARCHAR(200) NOT NULL COMMENT 'Display name',
  `CATEGORY` ENUM('cost','performance','sizing','leadtime','staffing','sustainability') NOT NULL COMMENT 'Benchmarks tab',
  `UNIT` VARCHAR(24) NOT NULL COMMENT 'Unit of every value of this measure',
  `USES_SITE_TYPE` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = values differ by site type',
  `USES_COOLING` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = values differ by cooling type',
  `USES_CLIMATE` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = values differ by climate',
  `USES_REGION` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = values differ by region',
  `USES_TIER` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = values differ by tier',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`BENCHMARK_MEASURE_ID`),
  UNIQUE KEY `UK_BENCHMARK_MEASURE_TENANT_ID_MEASURE_CODE` (`TENANT_ID`, `MEASURE_CODE`),
  UNIQUE KEY `UK_BENCHMARK_MEASURE_TENANT_ID_BENCHMARK_MEASURE_ID` (`TENANT_ID`, `BENCHMARK_MEASURE_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Measures a benchmark value can be given for; the measure fixes the unit, the tab and which applies-to fields matter.';

-- BENCHMARK: Identity of one benchmark case: a measure plus the applies-to fields. Values live in BENCHMARK_VERSION; one active case per measure.
-- Related tables: BENCHMARK → BENCHMARK_MEASURE; ← BENCHMARK_VERSION
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `BENCHMARK` (
  `BENCHMARK_ID` INT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of BENCHMARK',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `BENCHMARK_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Benchmark id (BM-0001)',
  `BENCHMARK_MEASURE_ID` SMALLINT UNSIGNED NOT NULL COMMENT 'Measure',
  `DC_TYPE_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Applies to site type (built-in or custom-…)',
  `COOLING_TYPE` ENUM('air-crah','air-economiser','chilled-water','in-row','rear-door','liquid-to-chip','immersion') NULL COMMENT 'Applies to cooling type',
  `CLIMATE` ENUM('cold','temperate','hot-dry','hot-humid') NULL COMMENT 'Applies to climate',
  `GEOGRAPHY_REGION_ID` INT UNSIGNED NULL COMMENT 'Applies to region',
  `TIER` ENUM('Tier I','Tier II','Tier III','Tier IV') NULL COMMENT 'Applies to tier',
  `CASE_KEY` VARCHAR(200) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (CONCAT_WS('|', BENCHMARK_MEASURE_ID, IFNULL(DC_TYPE_KEY,'*'), IFNULL(COOLING_TYPE,'*'), IFNULL(CLIMATE,'*'), IFNULL(GEOGRAPHY_REGION_ID,'*'), IFNULL(TIER,'*'))) STORED NOT NULL COMMENT 'Measure + applies-to fields in one key (generated)',
  `RETIRED_AT` DATETIME(3) NULL COMMENT 'When retired; values are retired, never deleted',
  `RETIRED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Who retired it',
  `RETIRE_REASON` VARCHAR(1000) NULL COMMENT 'Why',
  `ACTIVE_CASE_KEY` VARCHAR(200) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF(RETIRED_AT IS NULL, CASE_KEY, NULL)) STORED NULL COMMENT 'CASE_KEY while active, NULL when retired (generated; makes active cases unique)',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`BENCHMARK_ID`),
  UNIQUE KEY `UK_BENCHMARK_TENANT_ID_BENCHMARK_CODE` (`TENANT_ID`, `BENCHMARK_CODE`),
  UNIQUE KEY `UK_BENCHMARK_TENANT_ID_ACTIVE_CASE_KEY` (`TENANT_ID`, `ACTIVE_CASE_KEY`),
  UNIQUE KEY `UK_BENCHMARK_TENANT_ID_BENCHMARK_ID` (`TENANT_ID`, `BENCHMARK_ID`),
  KEY `IDX_BENCHMARK_TENANT_ID_BENCHMARK_MEASURE_ID` (`TENANT_ID`, `BENCHMARK_MEASURE_ID`),
  KEY `IDX_BENCHMARK_TENANT_ID_GEOGRAPHY_REGION_ID` (`TENANT_ID`, `GEOGRAPHY_REGION_ID`),
  CONSTRAINT `CK_BENCHMARK_01` CHECK ((RETIRED_AT IS NULL) = (RETIRED_BY IS NULL)),
  CONSTRAINT `FK_BENCHMARK_BENCHMARK_MEASURE_ID` FOREIGN KEY (`TENANT_ID`, `BENCHMARK_MEASURE_ID`) REFERENCES `BENCHMARK_MEASURE` (`TENANT_ID`, `BENCHMARK_MEASURE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_BENCHMARK_GEOGRAPHY_REGION_ID` FOREIGN KEY (`TENANT_ID`, `GEOGRAPHY_REGION_ID`) REFERENCES `GEOGRAPHY_REGION` (`TENANT_ID`, `GEOGRAPHY_REGION_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Identity of one benchmark case: a measure plus the applies-to fields. Values live in BENCHMARK_VERSION; one active case per measure.';

-- BENCHMARK_VERSION: One version of a benchmark value. Changing a confirmed value creates an Awaiting approval version; approval publishes it and supersedes the old one (DATA-020).
-- Related tables: BENCHMARK_VERSION → BENCHMARK
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `BENCHMARK_VERSION` (
  `BENCHMARK_VERSION_ID` INT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of BENCHMARK_VERSION',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `BENCHMARK_ID` INT UNSIGNED NOT NULL COMMENT 'Benchmark case',
  `VERSION_NO` SMALLINT UNSIGNED NOT NULL COMMENT 'Version number',
  `VERSION_STATUS` ENUM('Draft','Awaiting approval','Published','Superseded','Rejected','Discarded') NOT NULL COMMENT 'State of this version: Awaiting approval → Published (current) → Superseded',
  `LABEL` VARCHAR(200) NOT NULL COMMENT 'Display name of the value',
  `LOW_VALUE` DECIMAL(20,6) NULL COMMENT 'Low end of the range',
  `TYPICAL_VALUE` DECIMAL(20,6) NULL COMMENT 'Typical value',
  `HIGH_VALUE` DECIMAL(20,6) NULL COMMENT 'High end of the range',
  `SOURCE` VARCHAR(200) NOT NULL COMMENT 'Source of the value',
  `SOURCE_DATE` DATE NOT NULL COMMENT 'As-of date of the source',
  `CONFIDENCE` ENUM('indicative','confirmed') NOT NULL COMMENT 'indicative saves directly; changing a confirmed value needs approval',
  `REQUEST_KIND` ENUM('new','change') NULL COMMENT 'For Awaiting approval: a new value or a change',
  `REQUESTED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Who requested the change',
  `REQUESTED_AT` DATETIME(3) NULL COMMENT 'When',
  `REQUEST_REASON` VARCHAR(1000) NULL COMMENT 'Why',
  `DECIDED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Capacity Planner who approved or rejected (not the requester)',
  `DECIDED_AT` DATETIME(3) NULL COMMENT 'When',
  `DECISION_REASON` VARCHAR(1000) NULL COMMENT 'Reason',
  `LIVE_KEY` INT UNSIGNED GENERATED ALWAYS AS (IF(VERSION_STATUS = 'Published', BENCHMARK_ID, NULL)) STORED NULL COMMENT 'One published version per case (generated)',
  `PENDING_KEY` INT UNSIGNED GENERATED ALWAYS AS (IF(VERSION_STATUS = 'Awaiting approval', BENCHMARK_ID, NULL)) STORED NULL COMMENT 'One pending version per case (generated)',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`BENCHMARK_VERSION_ID`),
  UNIQUE KEY `UK_BENCHMARK_VERSION_TENANT_ID_BENCHMARK_ID_VERSION_NO` (`TENANT_ID`, `BENCHMARK_ID`, `VERSION_NO`),
  UNIQUE KEY `UK_BENCHMARK_VERSION_LIVE_KEY` (`LIVE_KEY`),
  UNIQUE KEY `UK_BENCHMARK_VERSION_PENDING_KEY` (`PENDING_KEY`),
  CONSTRAINT `CK_BENCHMARK_VERSION_01` CHECK (LOW_VALUE IS NULL OR TYPICAL_VALUE IS NULL OR LOW_VALUE <= TYPICAL_VALUE),
  CONSTRAINT `CK_BENCHMARK_VERSION_02` CHECK (TYPICAL_VALUE IS NULL OR HIGH_VALUE IS NULL OR TYPICAL_VALUE <= HIGH_VALUE),
  CONSTRAINT `CK_BENCHMARK_VERSION_03` CHECK (LOW_VALUE IS NULL OR HIGH_VALUE IS NULL OR LOW_VALUE <= HIGH_VALUE),
  CONSTRAINT `CK_BENCHMARK_VERSION_04` CHECK (COALESCE(LOW_VALUE, TYPICAL_VALUE, HIGH_VALUE) IS NOT NULL),
  CONSTRAINT `CK_BENCHMARK_VERSION_05` CHECK (VERSION_STATUS <> 'Awaiting approval' OR REQUESTED_BY IS NOT NULL),
  CONSTRAINT `CK_BENCHMARK_VERSION_06` CHECK (VERSION_STATUS NOT IN ('Draft','Discarded')),
  CONSTRAINT `CK_BENCHMARK_VERSION_07` CHECK (DECIDED_BY IS NULL OR REQUESTED_BY IS NULL OR DECIDED_BY <> REQUESTED_BY),
  CONSTRAINT `FK_BENCHMARK_VERSION_BENCHMARK_ID` FOREIGN KEY (`TENANT_ID`, `BENCHMARK_ID`) REFERENCES `BENCHMARK` (`TENANT_ID`, `BENCHMARK_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='One version of a benchmark value. Changing a confirmed value creates an Awaiting approval version; approval publishes it and supersedes the old one (DATA-020).';

-- APPROVAL_DELEGATION: Delegation of an approving role from one user to another for a period.
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `APPROVAL_DELEGATION` (
  `APPROVAL_DELEGATION_ID` INT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of APPROVAL_DELEGATION',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `DELEGATION_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Delegation id (DLG-001)',
  `ROLE_NAME` VARCHAR(100) NOT NULL COMMENT 'Approving role delegated',
  `FROM_USER_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User who delegates (Platform Engineering)',
  `FROM_NAME` VARCHAR(200) NOT NULL COMMENT 'Display name as at the delegation (snapshot, never refreshed)',
  `TO_USER_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User who receives the role',
  `TO_NAME` VARCHAR(200) NOT NULL COMMENT 'Display name as at the delegation (snapshot, never refreshed)',
  `START_DATE` DATE NOT NULL COMMENT 'First day',
  `END_DATE` DATE NOT NULL COMMENT 'Last day',
  `REASON` VARCHAR(1000) NULL COMMENT 'Reason',
  `STATUS` ENUM('Active','Revoked') NOT NULL DEFAULT 'Active' COMMENT 'State',
  `REVOKED_AT` DATETIME(3) NULL COMMENT 'When revoked',
  `REVOKED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Who revoked',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`APPROVAL_DELEGATION_ID`),
  UNIQUE KEY `UK_APPROVAL_DELEGATION_TENANT_ID_DELEGATION_CODE` (`TENANT_ID`, `DELEGATION_CODE`),
  UNIQUE KEY `UK_APPROVAL_DELEGATION_TENANT_ID_APPROVAL_DELEGATION_ID` (`TENANT_ID`, `APPROVAL_DELEGATION_ID`),
  KEY `IDX_APPROVAL_DELEGATION_TENANT_ID_TO_USER_ID_STATUS` (`TENANT_ID`, `TO_USER_ID`, `STATUS`),
  KEY `IDX_APPROVAL_DELEGATION_TENANT_ID_FROM_USER_ID` (`TENANT_ID`, `FROM_USER_ID`),
  CONSTRAINT `CK_APPROVAL_DELEGATION_01` CHECK (START_DATE <= END_DATE),
  CONSTRAINT `CK_APPROVAL_DELEGATION_02` CHECK (FROM_USER_ID <> TO_USER_ID),
  CONSTRAINT `CK_APPROVAL_DELEGATION_03` CHECK (STATUS <> 'Revoked' OR REVOKED_AT IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Delegation of an approving role from one user to another for a period.';

-- PLAN: A capacity / build plan (BRD 7.9). A revision (B, C …) is its own row pointing at the plan it revises; approved figures are frozen in PLAN_BASELINE.
-- Related tables: PLAN → PLAN_TEMPLATE, PLAN_TEMPLATE_VERSION, PLAN (revision / parent); ← every PLAN_* table, PLAN_REVIEW, WRITEBACK_REQUEST
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN` (
  `PLAN_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Plan id shown to users (PLN-0001)',
  `REVISION_LETTER` CHAR(1) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'A' COMMENT 'Revision letter; A = original',
  `REVISION_OF_PLAN_ID` BIGINT UNSIGNED NULL COMMENT 'Approved plan this revision changes',
  `PARENT_PLAN_ID` BIGINT UNSIGNED NULL COMMENT 'Portfolio / programme plan this plan was split from',
  `TITLE` VARCHAR(200) NOT NULL COMMENT 'Plan title',
  `PLAN_SCOPE` ENUM('rack','pod','hall','retrofit','plant','network','expansion','new-dc','portfolio','migration','edge','server-refresh','network-refresh','rack-replace') NOT NULL COMMENT 'Plan family',
  `STATUS` ENUM('Draft','In review','Approved','Executing','Completed','Rejected','On hold','Cancelled') NOT NULL DEFAULT 'Draft' COMMENT 'Plan state',
  `PLAN_TEMPLATE_ID` INT UNSIGNED NOT NULL COMMENT 'Plan type',
  `PLAN_TEMPLATE_VERSION_ID` INT UNSIGNED NULL COMMENT 'Plan type version the plan is pinned to',
  `DC_TYPE_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Kind of site (built-in or custom-…)',
  `INV_SITE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Datacenter id in Inventory; NULL for a new site, region or portfolio plan',
  `INV_CAMPUS_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Campus id in Inventory',
  `GEOGRAPHY_REGION_ID` INT UNSIGNED NULL COMMENT 'Region for a new-site or portfolio plan',
  `NEW_SITE_NAME` VARCHAR(200) NULL COMMENT 'Name of a site that does not exist yet',
  `PEER_INV_SITE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Second site of a two-site plan (network / migration)',
  `CLIMATE` ENUM('cold','temperate','hot-dry','hot-humid') NOT NULL COMMENT 'Climate of the site',
  `INTENT` VARCHAR(2000) NOT NULL COMMENT 'Why the plan exists',
  `OWNER_USER_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Plan owner; the name is read from Platform Engineering',
  `REQUESTED_BY_NAME` VARCHAR(200) NOT NULL COMMENT 'Requester (team or person)',
  `DESIGN_POWER_KW` DECIMAL(12,3) NOT NULL COMMENT 'Design IT power, kW',
  `TARGET_GO_LIVE` DATE NOT NULL COMMENT 'Needed-by date',
  `DEMAND_GPU_PCT` DECIMAL(5,2) NOT NULL COMMENT 'Workload mix: GPU share',
  `DEMAND_COMPUTE_PCT` DECIMAL(5,2) NOT NULL COMMENT 'Workload mix: compute share',
  `DEMAND_STORAGE_PCT` DECIMAL(5,2) NOT NULL COMMENT 'Workload mix: storage share',
  `DENSITY_KW_PER_RACK` DECIMAL(12,3) NOT NULL COMMENT 'Design rack density, kW',
  `TENANCY` ENUM('single','multi') NOT NULL COMMENT 'Tenancy',
  `GROWTH_PCT_PER_YEAR` DECIMAL(5,2) NOT NULL COMMENT 'Demand growth per year',
  `REVENUE_PER_KW_MONTH_USD` DECIMAL(16,2) NULL COMMENT 'Revenue per kW-month used in the business case',
  `TARIFF_USD_PER_KWH` DECIMAL(12,5) NULL COMMENT 'Tariff used in the business case',
  `WIZARD_STEP_NO` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Wizard step the draft was left on',
  `WIZARD_STEP_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Wizard step key',
  `IS_AI_ASSISTED` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = AI filled inputs',
  `SUBMITTED_AT` DATETIME(3) NULL COMMENT 'Last submission for approval',
  `SUBMITTED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Who submitted',
  `APPROVAL_AMOUNT_USD` DECIMAL(16,2) NULL COMMENT 'CapEx the approval band was set from',
  `APPROVAL_BAND` VARCHAR(50) NULL COMMENT 'CapEx band that sets the approval path',
  `HELD_AT` DATETIME(3) NULL COMMENT 'When put on hold',
  `HELD_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Who put it on hold',
  `HOLD_REASON` VARCHAR(1000) NULL COMMENT 'Why',
  `STATUS_BEFORE_HOLD` ENUM('Draft','In review','Approved','Executing','Completed','Rejected','On hold','Cancelled') NULL COMMENT 'Status to return to when the hold is lifted',
  `CANCELLED_AT` DATETIME(3) NULL COMMENT 'When cancelled',
  `CANCELLED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Who cancelled',
  `CANCEL_REASON` VARCHAR(1000) NULL COMMENT 'Why',
  `IP_PLAN_AT` DATETIME(3) NULL COMMENT 'When the IP plan (PLAN_IP_REQUEST) was last computed',
  `PRJ_PROGRAM_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Programme in Programs & Projects after hand-over',
  `PRJ_PROJECT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Project in Programs & Projects after hand-over',
  `PROCESS_INSTANCE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Workflow process instance driving the plan',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_ID`),
  UNIQUE KEY `UK_PLAN_TENANT_ID_PLAN_CODE_REVISION_LETTER` (`TENANT_ID`, `PLAN_CODE`, `REVISION_LETTER`),
  UNIQUE KEY `UK_PLAN_PLAN_ID_TENANT_ID` (`PLAN_ID`, `TENANT_ID`),
  UNIQUE KEY `UK_PLAN_TENANT_ID_PLAN_ID` (`TENANT_ID`, `PLAN_ID`),
  KEY `IDX_PLAN_TENANT_ID_STATUS` (`TENANT_ID`, `STATUS`),
  KEY `IDX_PLAN_TENANT_ID_INV_SITE_ID_STATUS` (`TENANT_ID`, `INV_SITE_ID`, `STATUS`),
  KEY `IDX_PLAN_TENANT_ID_PLAN_TEMPLATE_ID` (`TENANT_ID`, `PLAN_TEMPLATE_ID`),
  KEY `IDX_PLAN_TENANT_ID_PLAN_TEMPLATE_VERSION_ID` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`),
  KEY `IDX_PLAN_TENANT_ID_REVISION_OF_PLAN_ID` (`TENANT_ID`, `REVISION_OF_PLAN_ID`),
  KEY `IDX_PLAN_TENANT_ID_PARENT_PLAN_ID` (`TENANT_ID`, `PARENT_PLAN_ID`),
  KEY `IDX_PLAN_TENANT_ID_GEOGRAPHY_REGION_ID` (`TENANT_ID`, `GEOGRAPHY_REGION_ID`),
  KEY `IDX_PLAN_REVISION_OF_PLAN_ID_TENANT_ID` (`REVISION_OF_PLAN_ID`, `TENANT_ID`),
  KEY `IDX_PLAN_PARENT_PLAN_ID_TENANT_ID` (`PARENT_PLAN_ID`, `TENANT_ID`),
  CONSTRAINT `CK_PLAN_01` CHECK (DEMAND_GPU_PCT + DEMAND_COMPUTE_PCT + DEMAND_STORAGE_PCT = 100),
  CONSTRAINT `CK_PLAN_02` CHECK (DESIGN_POWER_KW >= 0),
  CONSTRAINT `CK_PLAN_03` CHECK (DENSITY_KW_PER_RACK >= 0),
  CONSTRAINT `CK_PLAN_04` CHECK (REVISION_LETTER BETWEEN 'A' AND 'Z'),
  CONSTRAINT `CK_PLAN_05` CHECK ((REVISION_LETTER = 'A') = (REVISION_OF_PLAN_ID IS NULL)),
  CONSTRAINT `CK_PLAN_06` CHECK (STATUS <> 'On hold' OR (HELD_AT IS NOT NULL AND STATUS_BEFORE_HOLD IS NOT NULL)),
  CONSTRAINT `CK_PLAN_07` CHECK (STATUS <> 'Cancelled' OR CANCELLED_AT IS NOT NULL),
  CONSTRAINT `CK_PLAN_08` CHECK (INV_SITE_ID IS NOT NULL OR NEW_SITE_NAME IS NOT NULL OR GEOGRAPHY_REGION_ID IS NOT NULL),
  CONSTRAINT `CK_PLAN_09` CHECK (GROWTH_PCT_PER_YEAR BETWEEN 0 AND 100),
  CONSTRAINT `CK_PLAN_10` CHECK (REVENUE_PER_KW_MONTH_USD >= 0),
  CONSTRAINT `CK_PLAN_11` CHECK (TARIFF_USD_PER_KWH >= 0),
  CONSTRAINT `CK_PLAN_12` CHECK (APPROVAL_AMOUNT_USD >= 0),
  CONSTRAINT `FK_PLAN_REVISION_OF_PLAN_ID` FOREIGN KEY (`REVISION_OF_PLAN_ID`, `TENANT_ID`) REFERENCES `PLAN` (`PLAN_ID`, `TENANT_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_PARENT_PLAN_ID` FOREIGN KEY (`PARENT_PLAN_ID`, `TENANT_ID`) REFERENCES `PLAN` (`PLAN_ID`, `TENANT_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_PLAN_TEMPLATE_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_TEMPLATE_ID`) REFERENCES `PLAN_TEMPLATE` (`TENANT_ID`, `PLAN_TEMPLATE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_PLAN_TEMPLATE_VERSION_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) REFERENCES `PLAN_TEMPLATE_VERSION` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_GEOGRAPHY_REGION_ID` FOREIGN KEY (`TENANT_ID`, `GEOGRAPHY_REGION_ID`) REFERENCES `GEOGRAPHY_REGION` (`TENANT_ID`, `GEOGRAPHY_REGION_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='A capacity / build plan (BRD 7.9). A revision (B, C …) is its own row pointing at the plan it revises; approved figures are frozen in PLAN_BASELINE.';

-- PLAN_MODULE_PIN: Module versions a plan is pinned to (with its plan type version); a module that moves on is reported as drift.
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_MODULE_PIN` (
  `PLAN_MODULE_PIN_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_MODULE_PIN',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `MODULE_TEMPLATE_ID` INT UNSIGNED NOT NULL COMMENT 'Module template',
  `PLAN_TEMPLATE_VERSION_ID` INT UNSIGNED NOT NULL COMMENT 'Pinned version of the module',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_MODULE_PIN_ID`),
  UNIQUE KEY `UK_PLAN_MODULE_PIN_TENANT_ID_PLAN_ID_MODULE_TEMPLATE_ID` (`TENANT_ID`, `PLAN_ID`, `MODULE_TEMPLATE_ID`),
  KEY `IDX_PLAN_MODULE_PIN_TENANT_ID_MODULE_TEMPLATE_ID` (`TENANT_ID`, `MODULE_TEMPLATE_ID`),
  KEY `IDX_PLAN_MODULE_PIN_TENANT_ID_PLAN_TEMPLATE_VERSION_ID` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`),
  CONSTRAINT `FK_PLAN_MODULE_PIN_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_MODULE_PIN_MODULE_TEMPLATE_ID` FOREIGN KEY (`TENANT_ID`, `MODULE_TEMPLATE_ID`) REFERENCES `PLAN_TEMPLATE` (`TENANT_ID`, `PLAN_TEMPLATE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_MODULE_PIN_PLAN_TEMPLATE_VERSION_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) REFERENCES `PLAN_TEMPLATE_VERSION` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Module versions a plan is pinned to (with its plan type version); a module that moves on is reported as drift.';

-- PLAN_INPUT: Input value of a plan and where it came from (user, requirement, template, benchmark, actual ...). Requirements are inputs with source = requirement.
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_INPUT` (
  `PLAN_INPUT_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_INPUT',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `INPUT_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Input key (PLAN_TEMPLATE_INPUT.INPUT_KEY)',
  `VALUE_TYPE` ENUM('number','text','bool') NOT NULL COMMENT 'Type of the value',
  `VALUE_NUMBER` DECIMAL(20,6) NULL COMMENT 'Value when VALUE_TYPE = number',
  `VALUE_TEXT` VARCHAR(500) NULL COMMENT 'Value when VALUE_TYPE = text',
  `VALUE_BOOL` TINYINT(1) NULL COMMENT 'Value when VALUE_TYPE = bool',
  `VALUE_SOURCE` ENUM('user','requirement','template','benchmark','actual','document','ai') NOT NULL COMMENT 'Where the value came from',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_INPUT_ID`),
  UNIQUE KEY `UK_PLAN_INPUT_TENANT_ID_PLAN_ID_INPUT_KEY` (`TENANT_ID`, `PLAN_ID`, `INPUT_KEY`),
  CONSTRAINT `CK_PLAN_INPUT_01` CHECK ((VALUE_TYPE = 'number') = (VALUE_NUMBER IS NOT NULL)),
  CONSTRAINT `CK_PLAN_INPUT_02` CHECK ((VALUE_TYPE = 'text') = (VALUE_TEXT IS NOT NULL)),
  CONSTRAINT `CK_PLAN_INPUT_03` CHECK ((VALUE_TYPE = 'bool') = (VALUE_BOOL IS NOT NULL)),
  CONSTRAINT `FK_PLAN_INPUT_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Input value of a plan and where it came from (user, requirement, template, benchmark, actual ...). Requirements are inputs with source = requirement.';

-- PLAN_PHASE: Build phase of a plan: go-live, IT kW, halls, racks.
-- Related tables: PLAN_PHASE ← PLAN_PHASE_INPUT, PLAN_PERMIT
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_PHASE` (
  `PLAN_PHASE_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_PHASE',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `PHASE_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Phase id within the plan (P1, P2 …)',
  `SORT_ORDER` SMALLINT UNSIGNED NOT NULL COMMENT 'Order',
  `NAME` VARCHAR(200) NOT NULL COMMENT 'Phase name',
  `GO_LIVE` DATE NOT NULL COMMENT 'Go-live date',
  `IT_KW` DECIMAL(12,3) NOT NULL COMMENT 'IT capacity delivered, kW',
  `HALLS` SMALLINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Halls delivered',
  `RACKS` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Racks delivered',
  `STATUS` ENUM('Planned','Approved','In delivery','Live') NOT NULL DEFAULT 'Planned' COMMENT 'Phase state',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_PHASE_ID`),
  UNIQUE KEY `UK_PLAN_PHASE_TENANT_ID_PLAN_ID_PHASE_CODE` (`TENANT_ID`, `PLAN_ID`, `PHASE_CODE`),
  UNIQUE KEY `UK_PLAN_PHASE_TENANT_ID_PLAN_ID_SORT_ORDER` (`TENANT_ID`, `PLAN_ID`, `SORT_ORDER`),
  UNIQUE KEY `UK_PLAN_PHASE_TENANT_ID_PLAN_PHASE_ID` (`TENANT_ID`, `PLAN_PHASE_ID`),
  CONSTRAINT `CK_PLAN_PHASE_01` CHECK (IT_KW >= 0),
  CONSTRAINT `FK_PLAN_PHASE_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Build phase of a plan: go-live, IT kW, halls, racks.';

