) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Input value that differs for one phase.';

-- PLAN_SCENARIO: What-if scenario of a plan; at most one preferred per plan.
-- Related tables: PLAN_SCENARIO ← PLAN_SCENARIO_INPUT, PLAN_SCENARIO_PHASE, PLAN_APPROVAL_ROUND, PLAN_BASELINE
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_SCENARIO` (
  `PLAN_SCENARIO_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_SCENARIO',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `SCENARIO_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Scenario id (SCN-001)',
  `NAME` VARCHAR(200) NOT NULL COMMENT 'Scenario name',
  `DESCRIPTION` VARCHAR(2000) NULL COMMENT 'What it changes',
  `IS_PREFERRED` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = preferred scenario',
