  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_SCENARIO_ID`),
  UNIQUE KEY `UK_PLAN_SCENARIO_TENANT_ID_PLAN_ID_SCENARIO_CODE` (`TENANT_ID`, `PLAN_ID`, `SCENARIO_CODE`),
  UNIQUE KEY `UK_PLAN_SCENARIO_PREFERRED_KEY` (`PREFERRED_KEY`),
  UNIQUE KEY `UK_PLAN_SCENARIO_TENANT_ID_PLAN_SCENARIO_ID` (`TENANT_ID`, `PLAN_SCENARIO_ID`),
  CONSTRAINT `FK_PLAN_SCENARIO_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='What-if scenario of a plan; at most one preferred per plan.';

