  UNIQUE KEY `UK_PLAN_APPROVAL_ROUND_OPEN_ROUND_KEY` (`OPEN_ROUND_KEY`),
  UNIQUE KEY `UK_PLAN_APPROVAL_ROUND_TENANT_ID_PLAN_APPROVAL_ROUND_ID` (`TENANT_ID`, `PLAN_APPROVAL_ROUND_ID`),
  KEY `IDX_PLAN_APPROVAL_ROUND_TENANT_ID_PLAN_SCENARIO_ID` (`TENANT_ID`, `PLAN_SCENARIO_ID`),
  CONSTRAINT `CK_PLAN_APPROVAL_ROUND_01` CHECK ((ROUND_OUTCOME = 'Open') = (CLOSED_AT IS NULL)),
  CONSTRAINT `CK_PLAN_APPROVAL_ROUND_02` CHECK (AMOUNT_USD >= 0),
  CONSTRAINT `FK_PLAN_APPROVAL_ROUND_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_APPROVAL_ROUND_PLAN_SCENARIO_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_SCENARIO_ID`) REFERENCES `PLAN_SCENARIO` (`TENANT_ID`, `PLAN_SCENARIO_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='One submission of a plan for approval and its outcome.';

-- PLAN_APPROVAL: Decision of one approval step in a round.
