  UNIQUE KEY `UK_PLAN_APPROVAL_TENANT_ID_PLAN_APPROVAL_ID` (`TENANT_ID`, `PLAN_APPROVAL_ID`),
  KEY `IDX_PLAN_APPROVAL_TENANT_ID_APPROVAL_DELEGATION_ID` (`TENANT_ID`, `APPROVAL_DELEGATION_ID`),
  KEY `IDX_PLAN_APPROVAL_TENANT_ID_APPROVER_USER_ID` (`TENANT_ID`, `APPROVER_USER_ID`),
  CONSTRAINT `CK_PLAN_APPROVAL_01` CHECK ((APPROVAL_DECISION = 'Pending') = (DECIDED_AT IS NULL)),
  CONSTRAINT `CK_PLAN_APPROVAL_02` CHECK (APPROVAL_DECISION <> 'Rejected' OR REASON IS NOT NULL),
  CONSTRAINT `CK_PLAN_APPROVAL_03` CHECK ((ON_BEHALF_OF_USER_ID IS NULL) = (APPROVAL_DELEGATION_ID IS NULL)),
  CONSTRAINT `FK_PLAN_APPROVAL_PLAN_APPROVAL_ROUND_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_APPROVAL_ROUND_ID`) REFERENCES `PLAN_APPROVAL_ROUND` (`TENANT_ID`, `PLAN_APPROVAL_ROUND_ID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_APPROVAL_APPROVAL_DELEGATION_ID` FOREIGN KEY (`TENANT_ID`, `APPROVAL_DELEGATION_ID`) REFERENCES `APPROVAL_DELEGATION` (`TENANT_ID`, `APPROVAL_DELEGATION_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Decision of one approval step in a round.';

