  `HARD_FAILS` SMALLINT UNSIGNED NOT NULL COMMENT 'Must-pass rules failing',
  `SOFT_WARNS` SMALLINT UNSIGNED NOT NULL COMMENT 'Should-pass rules warning',
  `READINESS_PCT` DECIMAL(5,2) NOT NULL COMMENT 'Readiness',
  `SNAPSHOT` JSON NOT NULL COMMENT 'Frozen inputs, phases, module versions, schedule and benchmark figures as approved',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_BASELINE_ID`),
  UNIQUE KEY `UK_PLAN_BASELINE_TENANT_ID_PLAN_ID` (`TENANT_ID`, `PLAN_ID`),
  KEY `IDX_PLAN_BASELINE_TENANT_ID_PLAN_SCENARIO_ID` (`TENANT_ID`, `PLAN_SCENARIO_ID`),
  KEY `IDX_PLAN_BASELINE_TENANT_ID_PLAN_TEMPLATE_VERSION_ID` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`),
  CONSTRAINT `CK_PLAN_BASELINE_01` CHECK (CAPEX_TOTAL_USD >= 0),
  CONSTRAINT `CK_PLAN_BASELINE_02` CHECK (OPEX_MONTHLY_USD >= 0),
  CONSTRAINT `CK_PLAN_BASELINE_03` CHECK (BOM_TOTAL_USD >= 0),
  CONSTRAINT `CK_PLAN_BASELINE_04` CHECK (DESIGN_POWER_KW >= 0),
  CONSTRAINT `CK_PLAN_BASELINE_05` CHECK (CONTINGENCY_USD >= 0),
  CONSTRAINT `CK_PLAN_BASELINE_06` CHECK (SOURCED_TOTAL_USD >= 0),
  CONSTRAINT `CK_PLAN_BASELINE_07` CHECK (BUY_TOTAL_USD >= 0),
  CONSTRAINT `CK_PLAN_BASELINE_08` CHECK (READINESS_PCT BETWEEN 0 AND 100),
  CONSTRAINT `FK_PLAN_BASELINE_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_BASELINE_PLAN_SCENARIO_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_SCENARIO_ID`) REFERENCES `PLAN_SCENARIO` (`TENANT_ID`, `PLAN_SCENARIO_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_BASELINE_PLAN_TEMPLATE_VERSION_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) REFERENCES `PLAN_TEMPLATE_VERSION` (`TENANT_ID`, `PLAN_TEMPLATE_VERSION_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Snapshot frozen at approval: pinned versions, headline figures and the full figures (DATA-022). Never updated.';

-- PLAN_CLOSEOUT: Close-out of a delivered plan: delivered kW, actual cost, measured load.
-- Related tables: PLAN_CLOSEOUT ← PLAN_CLOSEOUT_CHECK
-- Domain: D. Planner · Updated: 2026-11-12
