  CONSTRAINT `CK_PLAN_CLOSEOUT_01` CHECK (DELIVERED_KW >= 0),
  CONSTRAINT `CK_PLAN_CLOSEOUT_02` CHECK (ACTUAL_CAPEX_USD >= 0),
  CONSTRAINT `CK_PLAN_CLOSEOUT_03` CHECK (ACTUAL_OPEX_MONTHLY_USD >= 0),
  CONSTRAINT `CK_PLAN_CLOSEOUT_04` CHECK (MEASURED_KW >= 0),
  CONSTRAINT `FK_PLAN_CLOSEOUT_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Close-out of a delivered plan: delivered kW, actual cost, measured load.';

