) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Close-out checklist line.';

-- PLAN_MATERIAL_OVERRIDE: Edit to the plan's bill of materials: quantity, model, vendor, source, removed or added line.
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_MATERIAL_OVERRIDE` (
  `PLAN_MATERIAL_OVERRIDE_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_MATERIAL_OVERRIDE',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `OVERRIDE_KEY` VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'kind|item|phase|site of the bill line, or ADD-n for an added line',
  `MATERIAL_KIND` VARCHAR(50) NOT NULL COMMENT 'Kind of material',
  `ITEM` VARCHAR(200) NOT NULL COMMENT 'Item',
  `PLAN_PHASE_ID` BIGINT UNSIGNED NULL COMMENT 'Phase of the bill line',
  `INV_SITE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Site (multi-site plans)',
  `QTY` DECIMAL(12,2) NULL COMMENT 'New quantity',
  `MODEL` VARCHAR(200) NULL COMMENT 'New model',
  `SUPPLY_SOURCE` ENUM('auto','site','stock','buy') NULL COMMENT 'Where the item comes from',
  `VENDOR` VARCHAR(200) NULL COMMENT 'Vendor or channel',
  `IS_REMOVED` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = line removed',
  `IS_ADDED` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = line added from the catalogue',
  `ADDED_CATEGORY` VARCHAR(50) NULL COMMENT 'Category of an added line',
  `ADDED_UNIT` VARCHAR(16) NULL COMMENT 'Unit of an added line',
  `ADDED_SPEC` VARCHAR(1000) NULL COMMENT 'Specification of an added line',
  `REASON` VARCHAR(1000) NULL COMMENT 'Why',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_MATERIAL_OVERRIDE_ID`),
  UNIQUE KEY `UK_PLAN_MATERIAL_OVERRIDE_TENANT_ID_PLAN_ID_OVERRIDE_KEY` (`TENANT_ID`, `PLAN_ID`, `OVERRIDE_KEY`),
  KEY `IDX_PLAN_MATERIAL_OVERRIDE_TENANT_ID_PLAN_PHASE_ID` (`TENANT_ID`, `PLAN_PHASE_ID`),
  CONSTRAINT `CK_PLAN_MATERIAL_OVERRIDE_01` CHECK (QTY IS NULL OR QTY >= 0),
  CONSTRAINT `CK_PLAN_MATERIAL_OVERRIDE_02` CHECK (NOT (IS_REMOVED = 1 AND IS_ADDED = 1)),
  CONSTRAINT `CK_PLAN_MATERIAL_OVERRIDE_03` CHECK (IS_ADDED = 0 OR ADDED_CATEGORY IS NOT NULL),
  CONSTRAINT `FK_PLAN_MATERIAL_OVERRIDE_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_MATERIAL_OVERRIDE_PLAN_PHASE_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_PHASE_ID`) REFERENCES `PLAN_PHASE` (`TENANT_ID`, `PLAN_PHASE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Edit to the plan''s bill of materials: quantity, model, vendor, source, removed or added line.';

-- PLAN_SITE: Site row of a multi-site plan (edge rollout, portfolio): existing site, edge location, candidate or campus.
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_SITE` (
  `PLAN_SITE_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_SITE',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `SITE_ROW_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Row id within the plan',
  `NAME` VARCHAR(200) NOT NULL COMMENT 'Site name',
  `REF_KIND` ENUM('dataCenter','edgeLocation','candidate','campus') NOT NULL COMMENT 'What the row points at',
  `REF_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Inventory site or edge location id (dataCenter / edgeLocation / campus); NULL for a candidate',
  `PLAN_CANDIDATE_SITE_ID` BIGINT UNSIGNED NULL COMMENT 'Candidate plot of the same plan (REF_KIND = candidate)',
  `VARIANT` VARCHAR(50) NULL COMMENT 'Site variant',
  `IT_KW` DECIMAL(12,3) NOT NULL COMMENT 'IT kW',
  `GO_LIVE` DATE NOT NULL COMMENT 'Go-live',
  `WAVE_NO` TINYINT UNSIGNED NULL COMMENT 'Rollout wave',
  `ROUTE` ENUM('expansion','new-dc','hall','pod','edge') NULL COMMENT 'How the site is delivered',
  `CAPEX_USD` DECIMAL(16,2) NULL COMMENT 'CapEx',
  `CHILD_PLAN_ID` BIGINT UNSIGNED NULL COMMENT 'Plan created for this site',
  `STATUS` ENUM('Proposed','Accepted','Rejected') NULL COMMENT 'Row state',
  `SUPPLY_KVA` DECIMAL(12,2) NULL COMMENT 'Grid supply, kVA',
  `LATITUDE` DECIMAL(9,6) NULL COMMENT 'Latitude',
  `LONGITUDE` DECIMAL(9,6) NULL COMMENT 'Longitude',
  `CITY` VARCHAR(100) NULL COMMENT 'City',
  `COUNTRY_CODE` CHAR(2) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'ISO country',
  `NOTES` VARCHAR(2000) NULL COMMENT 'Notes',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_SITE_ID`),
  UNIQUE KEY `UK_PLAN_SITE_TENANT_ID_PLAN_ID_SITE_ROW_CODE` (`TENANT_ID`, `PLAN_ID`, `SITE_ROW_CODE`),
  KEY `IDX_PLAN_SITE_TENANT_ID_CHILD_PLAN_ID` (`TENANT_ID`, `CHILD_PLAN_ID`),
  KEY `IDX_PLAN_SITE_TENANT_ID_PLAN_ID_PLAN_CANDIDATE_SITE_ID` (`TENANT_ID`, `PLAN_ID`, `PLAN_CANDIDATE_SITE_ID`),
  CONSTRAINT `CK_PLAN_SITE_01` CHECK (LATITUDE IS NULL OR LATITUDE BETWEEN -90 AND 90),
  CONSTRAINT `CK_PLAN_SITE_02` CHECK (LONGITUDE IS NULL OR LONGITUDE BETWEEN -180 AND 180),
  CONSTRAINT `CK_PLAN_SITE_03` CHECK (IT_KW >= 0),
  CONSTRAINT `CK_PLAN_SITE_04` CHECK ((REF_KIND = 'candidate') = (PLAN_CANDIDATE_SITE_ID IS NOT NULL)),
  CONSTRAINT `CK_PLAN_SITE_05` CHECK (REF_KIND = 'candidate' OR REF_ID IS NOT NULL),
  CONSTRAINT `CK_PLAN_SITE_06` CHECK (CAPEX_USD >= 0),
  CONSTRAINT `CK_PLAN_SITE_07` CHECK (SUPPLY_KVA >= 0),
  CONSTRAINT `FK_PLAN_SITE_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_SITE_PLAN_CANDIDATE_SITE_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`, `PLAN_CANDIDATE_SITE_ID`) REFERENCES `PLAN_CANDIDATE_SITE` (`TENANT_ID`, `PLAN_ID`, `PLAN_CANDIDATE_SITE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_SITE_CHILD_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `CHILD_PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Site row of a multi-site plan (edge rollout, portfolio): existing site, edge location, candidate or campus.';

-- PLAN_CANDIDATE_SITE: Candidate plot for a new-site plan, scored on land, grid, water, fibre and hazards.
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_CANDIDATE_SITE` (
  `PLAN_CANDIDATE_SITE_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_CANDIDATE_SITE',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `CANDIDATE_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Candidate id within the plan',
  `NAME` VARCHAR(200) NOT NULL COMMENT 'Name',
  `LATITUDE` DECIMAL(9,6) NULL COMMENT 'Latitude',
  `LONGITUDE` DECIMAL(9,6) NULL COMMENT 'Longitude',
  `GEOGRAPHY_REGION_ID` INT UNSIGNED NULL COMMENT 'Region',
  `CLIMATE` ENUM('cold','temperate','hot-dry','hot-humid') NULL COMMENT 'Climate',
  `PLOT_HA` DECIMAL(10,2) NOT NULL COMMENT 'Plot, hectares',
  `BUILDABLE_HA` DECIMAL(10,2) NOT NULL COMMENT 'Buildable, hectares',
  `ZONING` ENUM('Zoned for data centre','Rezoning needed','Unknown') NOT NULL COMMENT 'Zoning',
  `GRID_OFFER_MVA` DECIMAL(10,2) NOT NULL COMMENT 'Grid offer, MVA',
  `GRID_ENERGISATION` DATE NOT NULL COMMENT 'Grid energisation date',
  `IS_GRID_FIRM` TINYINT(1) NOT NULL COMMENT '1 = firm grid offer',
  `WATER_M3_PER_DAY` DECIMAL(12,2) NOT NULL COMMENT 'Water, m³/day',
  `FIBRE_ROUTES` TINYINT UNSIGNED NOT NULL COMMENT 'Fibre routes',
  `KM_TO_POP` DECIMAL(8,2) NOT NULL COMMENT 'Distance to POP, km',
  `IS_FLOOD_ZONE` TINYINT(1) NOT NULL COMMENT '1 = flood zone',
  `IS_SEISMIC_ZONE` TINYINT(1) NOT NULL COMMENT '1 = seismic zone',
  `LAND_COST_USD` DECIMAL(16,2) NOT NULL COMMENT 'Land cost',
  `TARIFF_USD_PER_KWH` DECIMAL(12,5) NULL COMMENT 'Local tariff',
  `INCENTIVES` VARCHAR(1000) NULL COMMENT 'Incentives',
  `IS_CHOSEN` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = chosen plot',
  `NOTES` VARCHAR(2000) NULL COMMENT 'Notes',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_CANDIDATE_SITE_ID`),
  UNIQUE KEY `UK_PLAN_CANDIDATE_SITE_TENANT_ID_PLAN_ID_CANDIDATE_CODE` (`TENANT_ID`, `PLAN_ID`, `CANDIDATE_CODE`),
  UNIQUE KEY `UK_PLAN_CANDIDATE_SITE_TENANT_ID_PLAN_ID_PLAN_CANDIDATE_SITE_ID` (`TENANT_ID`, `PLAN_ID`, `PLAN_CANDIDATE_SITE_ID`),
  KEY `IDX_PLAN_CANDIDATE_SITE_TENANT_ID_GEOGRAPHY_REGION_ID` (`TENANT_ID`, `GEOGRAPHY_REGION_ID`),
  CONSTRAINT `CK_PLAN_CANDIDATE_SITE_01` CHECK (BUILDABLE_HA <= PLOT_HA),
  CONSTRAINT `CK_PLAN_CANDIDATE_SITE_02` CHECK (LATITUDE IS NULL OR LATITUDE BETWEEN -90 AND 90),
  CONSTRAINT `CK_PLAN_CANDIDATE_SITE_03` CHECK (LONGITUDE IS NULL OR LONGITUDE BETWEEN -180 AND 180),
  CONSTRAINT `CK_PLAN_CANDIDATE_SITE_04` CHECK (GRID_OFFER_MVA >= 0),
  CONSTRAINT `CK_PLAN_CANDIDATE_SITE_05` CHECK (WATER_M3_PER_DAY >= 0),
  CONSTRAINT `CK_PLAN_CANDIDATE_SITE_06` CHECK (KM_TO_POP >= 0),
  CONSTRAINT `CK_PLAN_CANDIDATE_SITE_07` CHECK (LAND_COST_USD >= 0),
  CONSTRAINT `CK_PLAN_CANDIDATE_SITE_08` CHECK (TARIFF_USD_PER_KWH >= 0),
  CONSTRAINT `FK_PLAN_CANDIDATE_SITE_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_CANDIDATE_SITE_GEOGRAPHY_REGION_ID` FOREIGN KEY (`TENANT_ID`, `GEOGRAPHY_REGION_ID`) REFERENCES `GEOGRAPHY_REGION` (`TENANT_ID`, `GEOGRAPHY_REGION_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Candidate plot for a new-site plan, scored on land, grid, water, fibre and hazards.';

-- PLAN_WAVE: Wave of a refresh / migration plan: what moves when, method, rollback and result.
-- Related tables: PLAN_WAVE ← PLAN_WAVE_RECORD, PLAN_DISPOSITION
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_WAVE` (
  `PLAN_WAVE_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_WAVE',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
