  `NAME` VARCHAR(200) NOT NULL COMMENT 'Name',
  `SORT_ORDER` SMALLINT UNSIGNED NOT NULL COMMENT 'Order',
  `WAVE_KIND` ENUM('pilot','wave','drain','works','repopulate','soak') NOT NULL COMMENT 'Kind',
  `FEED_SIDE` ENUM('A','B') NULL COMMENT 'Power side worked on',
  `METHOD` VARCHAR(200) NULL COMMENT 'Method',
  `WINDOW_START` DATETIME(3) NOT NULL COMMENT 'Window start',
  `WINDOW_END` DATETIME(3) NOT NULL COMMENT 'Window end',
  `CREW_HOURS` DECIMAL(8,2) NULL COMMENT 'Crew hours',
  `ROLLBACK_TEXT` VARCHAR(1000) NOT NULL COMMENT 'Rollback',
  `ACCEPTANCE` VARCHAR(1000) NULL COMMENT 'Acceptance',
  `ITSM_CHANGE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Change request (ITSM)',
  `ITSM_MAINTENANCE_WINDOW_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Maintenance window (ITSM)',
  `PRJ_ATP_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Acceptance test (Programs & Projects commissioning)',
  `STATUS` ENUM('Planned','Scheduled','In progress','Closed','Rolled back','Cancelled') NOT NULL DEFAULT 'Planned' COMMENT 'State',
  `CLOSED_AT` DATETIME(3) NULL COMMENT 'Closed',
  `CLOSED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Closed by',
  `ACTUAL_DOWNTIME_MIN` INT UNSIGNED NULL COMMENT 'Actual downtime, minutes',
  `IT_KW` DECIMAL(12,3) NULL COMMENT 'IT kW moved',
  `NOTES` VARCHAR(2000) NULL COMMENT 'Notes',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_WAVE_ID`),
  UNIQUE KEY `UK_PLAN_WAVE_TENANT_ID_PLAN_ID_WAVE_CODE` (`TENANT_ID`, `PLAN_ID`, `WAVE_CODE`),
  UNIQUE KEY `UK_PLAN_WAVE_TENANT_ID_PLAN_WAVE_ID` (`TENANT_ID`, `PLAN_WAVE_ID`),
  KEY `IDX_PLAN_WAVE_ITSM_CHANGE_ID` (`ITSM_CHANGE_ID`),
  CONSTRAINT `CK_PLAN_WAVE_01` CHECK (WINDOW_START < WINDOW_END),
  CONSTRAINT `CK_PLAN_WAVE_02` CHECK (STATUS NOT IN ('Closed','Rolled back') OR CLOSED_AT IS NOT NULL),
  CONSTRAINT `CK_PLAN_WAVE_03` CHECK (CREW_HOURS >= 0),
  CONSTRAINT `CK_PLAN_WAVE_04` CHECK (IT_KW >= 0),
  CONSTRAINT `FK_PLAN_WAVE_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Wave of a refresh / migration plan: what moves when, method, rollback and result.';

