-- PLAN_DISPOSITION: What happens to each record of a migration / exit (move, retire, cease, re-terminate …).
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_DISPOSITION` (
  `PLAN_DISPOSITION_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_DISPOSITION',
