  `MODULE_RECORD_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Record id in its module',
  `LABEL` VARCHAR(200) NOT NULL COMMENT 'Name as at disposal (snapshot, never refreshed)',
  `DISPOSITION` ENUM('move','retire','dispose','keep','hand-back','cease','re-terminate','release','end','renew') NOT NULL COMMENT 'Disposition',
  `TARGET_REF` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Where it goes',
