  `COST_USD` DECIMAL(16,2) NULL COMMENT 'Cost',
  `NOTES` VARCHAR(2000) NULL COMMENT 'Notes',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_DISPOSITION_ID`),
  UNIQUE KEY `UK_PD_TENANT_ID_P_ID_DISPOSED_RECORD_TYPE_MODULE_RECORD_ID` (`TENANT_ID`, `PLAN_ID`, `DISPOSED_RECORD_TYPE`, `MODULE_RECORD_ID`),
  KEY `IDX_PLAN_DISPOSITION_TENANT_ID_PLAN_WAVE_ID` (`TENANT_ID`, `PLAN_WAVE_ID`),
  CONSTRAINT `CK_PLAN_DISPOSITION_01` CHECK (COST_USD >= 0),
  CONSTRAINT `FK_PLAN_DISPOSITION_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_DISPOSITION_PLAN_WAVE_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_WAVE_ID`) REFERENCES `PLAN_WAVE` (`TENANT_ID`, `PLAN_WAVE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='What happens to each record of a migration / exit (move, retire, cease, re-terminate …).';

-- PLAN_MODEL_MAPPING: Old model → new model mapping of a refresh plan.
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_MODEL_MAPPING` (
  `PLAN_MODEL_MAPPING_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_MODEL_MAPPING',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `MAPPING_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Row id',
  `OLD_MODEL` VARCHAR(200) NOT NULL COMMENT 'Old model',
  `ROLE` VARCHAR(50) NULL COMMENT 'Role',
  `OLD_COUNT` INT UNSIGNED NOT NULL COMMENT 'Old units',
  `NEW_MODEL` VARCHAR(200) NOT NULL COMMENT 'New model',
  `RATIO` DECIMAL(6,3) NOT NULL COMMENT 'New per old',
  `OLD_UNIT_DISPOSITION` ENUM('dispose','keep','resell') NOT NULL COMMENT 'What happens to the old units',
  `NEW_UNITS` INT UNSIGNED NOT NULL COMMENT 'New units',
  `NEW_KW` DECIMAL(12,3) NOT NULL COMMENT 'New kW',
  `OLD_KW` DECIMAL(12,3) NOT NULL COMMENT 'Old kW',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_MODEL_MAPPING_ID`),
  UNIQUE KEY `UK_PLAN_MODEL_MAPPING_TENANT_ID_PLAN_ID_MAPPING_CODE` (`TENANT_ID`, `PLAN_ID`, `MAPPING_CODE`),
  CONSTRAINT `CK_PLAN_MODEL_MAPPING_01` CHECK (RATIO > 0),
  CONSTRAINT `CK_PLAN_MODEL_MAPPING_02` CHECK (NEW_KW >= 0),
  CONSTRAINT `CK_PLAN_MODEL_MAPPING_03` CHECK (OLD_KW >= 0),
  CONSTRAINT `FK_PLAN_MODEL_MAPPING_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Old model → new model mapping of a refresh plan.';

