-- PLAN_RETROFIT_RACK: Rack a retrofit plan upgrades, or uses as swing space.
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_RETROFIT_RACK` (
  `PLAN_RETROFIT_RACK_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_RETROFIT_RACK',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `INV_RACK_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Rack (Inventory)',
  `RACK_ROLE` ENUM('retrofit','swing') NOT NULL COMMENT 'Role',
  `TARGET_KW` DECIMAL(12,3) NULL COMMENT 'Target kW (retrofit)',
  `READINESS` ENUM('ready','kit','new-cabinet') NULL COMMENT 'What the rack needs',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_RETROFIT_RACK_ID`),
  UNIQUE KEY `UK_PLAN_RETROFIT_RACK_TENANT_ID_PLAN_ID_INV_RACK_ID` (`TENANT_ID`, `PLAN_ID`, `INV_RACK_ID`),
  CONSTRAINT `CK_PLAN_RETROFIT_RACK_01` CHECK (RACK_ROLE = 'swing' OR TARGET_KW IS NOT NULL),
  CONSTRAINT `FK_PLAN_RETROFIT_RACK_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Rack a retrofit plan upgrades, or uses as swing space.';

-- PLAN_EXECUTION: One run of "Start the build": hands the plan to Delivery and records what it created.
-- Related tables: PLAN_EXECUTION ← PLAN_EXECUTION_STEP, PLAN_CREATED_RECORD
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_EXECUTION` (
  `PLAN_EXECUTION_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_EXECUTION',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `EXECUTION_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Run id',
  `VEHICLE` ENUM('programme','project','change','portfolio') NOT NULL COMMENT 'Delivery vehicle',
  `STARTED_AT` DATETIME(3) NOT NULL COMMENT 'Started',
  `STARTED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Started by',
  `COMPLETED_AT` DATETIME(3) NULL COMMENT 'Finished',
  `RUN_OUTCOME` ENUM('Running','Succeeded','Partly failed','Failed') NOT NULL DEFAULT 'Running' COMMENT 'Outcome',
  `DELIVERY_PROCESS_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Delivery process',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_EXECUTION_ID`),
  UNIQUE KEY `UK_PLAN_EXECUTION_TENANT_ID_EXECUTION_CODE` (`TENANT_ID`, `EXECUTION_CODE`),
  UNIQUE KEY `UK_PLAN_EXECUTION_TENANT_ID_PLAN_EXECUTION_ID` (`TENANT_ID`, `PLAN_EXECUTION_ID`),
  KEY `IDX_PLAN_EXECUTION_TENANT_ID_PLAN_ID` (`TENANT_ID`, `PLAN_ID`),
  CONSTRAINT `FK_PLAN_EXECUTION_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='One run of "Start the build": hands the plan to Delivery and records what it created.';

-- PLAN_EXECUTION_STEP: Step of a build run and its result.
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_EXECUTION_STEP` (
  `PLAN_EXECUTION_STEP_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_EXECUTION_STEP',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_EXECUTION_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Run',
  `STEP_KEY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Step',
  `STATUS` ENUM('Done','Failed','Skipped') NOT NULL COMMENT 'Result',
  `ERROR_MESSAGE` VARCHAR(1000) NULL COMMENT 'Error',
  `FINISHED_AT` DATETIME(3) NOT NULL COMMENT 'When',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_EXECUTION_STEP_ID`),
  UNIQUE KEY `UK_PLAN_EXECUTION_STEP_TENANT_ID_PLAN_EXECUTION_ID_STEP_KEY` (`TENANT_ID`, `PLAN_EXECUTION_ID`, `STEP_KEY`),
  CONSTRAINT `CK_PLAN_EXECUTION_STEP_01` CHECK (STATUS <> 'Failed' OR ERROR_MESSAGE IS NOT NULL),
  CONSTRAINT `FK_PLAN_EXECUTION_STEP_PLAN_EXECUTION_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_EXECUTION_ID`) REFERENCES `PLAN_EXECUTION` (`TENANT_ID`, `PLAN_EXECUTION_ID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Step of a build run and its result.';

-- PLAN_CREATED_RECORD: Record a plan created in a platform module (project, change, PO, subnet, VLAN, permit, reservation, planned rack / device …).
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_CREATED_RECORD` (
  `PLAN_CREATED_RECORD_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_CREATED_RECORD',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `PLAN_EXECUTION_ID` BIGINT UNSIGNED NULL COMMENT 'Run that created it',
  `TARGET_MODULE` ENUM('INV','IPL','IPM','ITSM','ALR','BSS','PRJ','SCM','SOC','PEN','OAP','IHB','AIF') NOT NULL COMMENT 'Module that owns the record',
  `RECORD_TYPE` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Record type (project, change, purchase-order, subnet, vlan, permit, reservation, rack, device, circuit …)',
  `MODULE_RECORD_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Record id in that module',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_CREATED_RECORD_ID`),
  UNIQUE KEY `UK_PCR_TENANT_ID_P_ID_TARGET_MODULE_RECORD_TYPE_MODULE_RECORD_ID` (`TENANT_ID`, `PLAN_ID`, `TARGET_MODULE`, `RECORD_TYPE`, `MODULE_RECORD_ID`),
  KEY `IDX_PLAN_CREATED_RECORD_TENANT_ID_PLAN_EXECUTION_ID` (`TENANT_ID`, `PLAN_EXECUTION_ID`),
  KEY `IDX_PLAN_CREATED_RECORD_TENANT_ID_TARGET_MODULE_MODULE_RECORD_ID` (`TENANT_ID`, `TARGET_MODULE`, `MODULE_RECORD_ID`),
  CONSTRAINT `FK_PLAN_CREATED_RECORD_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_CREATED_RECORD_PLAN_EXECUTION_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_EXECUTION_ID`) REFERENCES `PLAN_EXECUTION` (`TENANT_ID`, `PLAN_EXECUTION_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Record a plan created in a platform module (project, change, PO, subnet, VLAN, permit, reservation, planned rack / device …).';

-- PLAN_REVIEW: Request sent to reviewers with the plan review pack (PDF, ZIP or link).
