  `REVIEW_LINK` VARCHAR(500) NOT NULL COMMENT 'Link to the review page',
  `PLAN_STATUS_AT_REQUEST` ENUM('Draft','In review','Approved','Executing','Completed','Rejected','On hold','Cancelled') NOT NULL COMMENT 'Plan status when sent',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
