  UNIQUE KEY `UK_PLAN_REVIEW_TENANT_ID_PLAN_REVIEW_ID` (`TENANT_ID`, `PLAN_REVIEW_ID`),
  UNIQUE KEY `UK_PLAN_REVIEW_TENANT_ID_PLAN_ID_PLAN_REVIEW_ID` (`TENANT_ID`, `PLAN_ID`, `PLAN_REVIEW_ID`),
  CONSTRAINT `FK_PLAN_REVIEW_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Request sent to reviewers with the plan review pack (PDF, ZIP or link).';

