) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='File sent with a review request.';

-- PLAN_REVIEW_COMMENT: Threaded comment on a section of the plan review document.
-- Domain: D. Planner · Updated: 2026-11-12
CREATE TABLE `PLAN_REVIEW_COMMENT` (
  `PLAN_REVIEW_COMMENT_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of PLAN_REVIEW_COMMENT',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PLAN_ID` BIGINT UNSIGNED NOT NULL COMMENT 'Plan',
  `PLAN_REVIEW_ID` BIGINT UNSIGNED NULL COMMENT 'Review request it answers (a review of the same plan)',
  `PARENT_COMMENT_ID` BIGINT UNSIGNED NULL COMMENT 'Comment it replies to (same plan); NULL = thread start',
  `COMMENT_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Comment id (RVC-1)',
  `REVISION_LETTER` CHAR(1) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Plan revision commented on',
  `SECTION_ID` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Section of the review document (4.1 …)',
  `SECTION_LABEL` VARCHAR(200) NOT NULL COMMENT 'Section title as at posting (snapshot, never refreshed)',
  `AUTHOR_USER_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Author',
  `AUTHOR_NAME` VARCHAR(200) NOT NULL COMMENT 'Name as at posting (snapshot, never refreshed)',
  `AUTHOR_ROLE` VARCHAR(100) NULL COMMENT 'Role',
  `POSTED_AT` DATETIME(3) NOT NULL COMMENT 'Posted',
  `BODY` VARCHAR(2000) NOT NULL COMMENT 'Comment',
  `STATUS` ENUM('Open','Resolved','Dismissed') NOT NULL DEFAULT 'Open' COMMENT 'State',
  `RESOLVED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Resolved by',
  `RESOLVED_AT` DATETIME(3) NULL COMMENT 'Resolved',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`PLAN_REVIEW_COMMENT_ID`),
  UNIQUE KEY `UK_PLAN_REVIEW_COMMENT_TENANT_ID_COMMENT_CODE` (`TENANT_ID`, `COMMENT_CODE`),
  UNIQUE KEY `UK_PLAN_REVIEW_COMMENT_PLAN_REVIEW_COMMENT_ID_TENANT_ID_PLAN_ID` (`PLAN_REVIEW_COMMENT_ID`, `TENANT_ID`, `PLAN_ID`),
  KEY `IDX_PLAN_REVIEW_COMMENT_TENANT_ID_PLAN_ID_SECTION_ID` (`TENANT_ID`, `PLAN_ID`, `SECTION_ID`),
  KEY `IDX_PLAN_REVIEW_COMMENT_TENANT_ID_PLAN_ID_PLAN_REVIEW_ID` (`TENANT_ID`, `PLAN_ID`, `PLAN_REVIEW_ID`),
  KEY `IDX_PLAN_REVIEW_COMMENT_PARENT_COMMENT_ID_TENANT_ID_PLAN_ID` (`PARENT_COMMENT_ID`, `TENANT_ID`, `PLAN_ID`),
  CONSTRAINT `CK_PLAN_REVIEW_COMMENT_01` CHECK ((STATUS = 'Open') = (RESOLVED_AT IS NULL)),
  CONSTRAINT `FK_PLAN_REVIEW_COMMENT_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_REVIEW_COMMENT_PLAN_REVIEW_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`, `PLAN_REVIEW_ID`) REFERENCES `PLAN_REVIEW` (`TENANT_ID`, `PLAN_ID`, `PLAN_REVIEW_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_PLAN_REVIEW_COMMENT_PARENT_COMMENT_ID` FOREIGN KEY (`PARENT_COMMENT_ID`, `TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN_REVIEW_COMMENT` (`PLAN_REVIEW_COMMENT_ID`, `TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Threaded comment on a section of the plan review document.';

-- MACD_CATALOGUE_ITEM: MACD catalogue item: what can be ordered, its SLA, charges and change class (BRD 7.13).
-- Related tables: MACD_CATALOGUE_ITEM ← MACD_CATALOGUE_ITEM_MODEL, MACD_CATALOGUE_STEP, MACD_REQUEST
-- Domain: E. MACD, compliance and imports · Updated: 2026-11-12
CREATE TABLE `MACD_CATALOGUE_ITEM` (
  `MACD_CATALOGUE_ITEM_ID` INT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of MACD_CATALOGUE_ITEM',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `ITEM_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Item code (MAC-A01)',
  `MACD_KIND` ENUM('Move','Add','Change','Disconnect') NOT NULL COMMENT 'Kind',
  `MACD_OBJECT` ENUM('Equipment','Cabinet','Power circuit','Cross-connect','Network port','IP addresses','GPU nodes','Access') NOT NULL COMMENT 'What it acts on',
  `NAME` VARCHAR(200) NOT NULL COMMENT 'Name',
  `DESCRIPTION` VARCHAR(2000) NOT NULL COMMENT 'Description',
  `SLA_STANDARD_H` SMALLINT UNSIGNED NOT NULL COMMENT 'Standard SLA, hours',
  `SLA_EXPEDITED_H` SMALLINT UNSIGNED NOT NULL COMMENT 'Expedited SLA, hours',
  `SLA_EMERGENCY_H` SMALLINT UNSIGNED NOT NULL DEFAULT 4 COMMENT 'Emergency SLA, hours',
  `CURRENCY_CODE` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Currency of the charges',
  `NRC_AMOUNT` DECIMAL(16,2) NOT NULL DEFAULT 0.00 COMMENT 'One-off charge per unit',
  `MRC_AMOUNT` DECIMAL(16,2) NOT NULL DEFAULT 0.00 COMMENT 'Monthly charge per unit',
  `UNIT` VARCHAR(24) NOT NULL COMMENT 'Unit ordered (U, kW, port, node …)',
  `IS_STANDARD_CHANGE` TINYINT(1) NOT NULL COMMENT '1 = runs as a pre-approved standard change',
  `NEEDS_SITE_ACCESS` TINYINT(1) NOT NULL COMMENT '1 = someone enters the site',
  `U_PER_UNIT` DECIMAL(6,2) NOT NULL DEFAULT 0.00 COMMENT 'Rack units per unit',
  `KW_PER_UNIT` DECIMAL(12,3) NOT NULL DEFAULT 0.000 COMMENT 'kW per unit',
  `RISK` ENUM('Low','Medium','High') NOT NULL COMMENT 'Change risk',
  `CHANGE_TITLE_TEMPLATE` VARCHAR(200) NOT NULL COMMENT 'Title of the change request it raises',
  `IS_ACTIVE` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = orderable',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`MACD_CATALOGUE_ITEM_ID`),
  UNIQUE KEY `UK_MACD_CATALOGUE_ITEM_TENANT_ID_ITEM_CODE` (`TENANT_ID`, `ITEM_CODE`),
  UNIQUE KEY `UK_MACD_CATALOGUE_ITEM_TENANT_ID_MACD_CATALOGUE_ITEM_ID` (`TENANT_ID`, `MACD_CATALOGUE_ITEM_ID`),
  CONSTRAINT `CK_MACD_CATALOGUE_ITEM_01` CHECK (SLA_EXPEDITED_H <= SLA_STANDARD_H),
  CONSTRAINT `CK_MACD_CATALOGUE_ITEM_02` CHECK (SLA_EMERGENCY_H <= SLA_EXPEDITED_H),
  CONSTRAINT `CK_MACD_CATALOGUE_ITEM_03` CHECK (NRC_AMOUNT >= 0),
  CONSTRAINT `CK_MACD_CATALOGUE_ITEM_04` CHECK (MRC_AMOUNT >= 0),
  CONSTRAINT `CK_MACD_CATALOGUE_ITEM_05` CHECK (U_PER_UNIT >= 0),
  CONSTRAINT `CK_MACD_CATALOGUE_ITEM_06` CHECK (KW_PER_UNIT >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='MACD catalogue item: what can be ordered, its SLA, charges and change class (BRD 7.13).';

