-- MACD_REQUEST: MACD request from a customer or internal team, through stages Draft → … → Completed, with SLA clock and the change it runs under.
-- Related tables: MACD_REQUEST → MACD_CATALOGUE_ITEM; ← MACD_REQUEST_DEVICE, MACD_REQUEST_CHECK, MACD_REQUEST_TASK, MACD_REQUEST_EVENT
-- Domain: E. MACD, compliance and imports · Updated: 2026-11-12
CREATE TABLE `MACD_REQUEST` (
  `MACD_REQUEST_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of MACD_REQUEST',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `INV_SITE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Datacenter (site) id in Plan to Build Inventory; row access follows the user''s site scope',
  `REQUEST_CODE` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Request id (MACD-…)',
  `MACD_CATALOGUE_ITEM_ID` INT UNSIGNED NOT NULL COMMENT 'Catalogue item ordered',
  `TITLE` VARCHAR(200) NOT NULL COMMENT 'Title',
  `DETAIL` VARCHAR(2000) NOT NULL COMMENT 'Detail',
  `INV_ROOM_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Room (Inventory)',
  `INV_RACK_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Rack (Inventory)',
  `TO_INV_RACK_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Target rack of a move',
  `BSS_CUSTOMER_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Customer (BSS); NULL = internal',
  `REQUESTER_NAME` VARCHAR(200) NOT NULL COMMENT 'Requester',
  `CHANNEL` ENUM('Customer portal','Account manager','Email','API','Internal') NOT NULL COMMENT 'Channel',
  `OWNER_USER_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Owner',
  `PRIORITY` ENUM('Standard','Expedited','Emergency') NOT NULL DEFAULT 'Standard' COMMENT 'Priority',
  `STAGE` ENUM('Draft','Submitted','Feasibility','Quote','Scheduled','In progress','Verification','Completed','Rejected','Cancelled') NOT NULL DEFAULT 'Draft' COMMENT 'Stage',
  `WANTED_BY` DATE NULL COMMENT 'Date the requester wants',
  `SUBMITTED_AT` DATETIME(3) NULL COMMENT 'Submitted (SLA clock starts); NULL while Draft',
  `DUE_AT` DATETIME(3) NULL COMMENT 'SLA due',
  `WINDOW_START` DATETIME(3) NULL COMMENT 'Work window start',
  `WINDOW_END` DATETIME(3) NULL COMMENT 'Work window end',
  `COMPLETED_AT` DATETIME(3) NULL COMMENT 'Completed',
  `QTY` DECIMAL(12,2) NOT NULL COMMENT 'Quantity',
  `U_DELTA` SMALLINT NOT NULL DEFAULT 0 COMMENT 'Rack units added (+) or freed (−)',
  `KW_DELTA` DECIMAL(12,3) NOT NULL DEFAULT 0.000 COMMENT 'kW added (+) or freed (−)',
  `CURRENCY_CODE` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Currency',
  `NRC_AMOUNT` DECIMAL(16,2) NOT NULL DEFAULT 0.00 COMMENT 'One-off charge',
  `MRC_DELTA` DECIMAL(16,2) NOT NULL DEFAULT 0.00 COMMENT 'Change of monthly charge (+/−)',
  `IS_BILLABLE` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = billed to the customer',
  `ITSM_CHANGE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Change request (ITSM)',
  `IPL_HOLD_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Space hold (Inventory Planning)',
  `EXTERNAL_REF` VARCHAR(50) NULL COMMENT 'External reference (cross-connect order id)',
  `WORK_REF` VARCHAR(50) NULL COMMENT 'Work order / field reference',
  `SLA_STATE` ENUM('On track','At risk','Breached','Met','Missed') NULL COMMENT 'SLA state at the last evaluation; NULL while Draft',
  `IS_FIRST_TIME_RIGHT` TINYINT(1) NULL COMMENT '1 = verified without rework',
  `REASON` VARCHAR(1000) NULL COMMENT 'Reject / cancel reason',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`MACD_REQUEST_ID`),
  UNIQUE KEY `UK_MACD_REQUEST_TENANT_ID_REQUEST_CODE` (`TENANT_ID`, `REQUEST_CODE`),
  UNIQUE KEY `UK_MACD_REQUEST_TENANT_ID_MACD_REQUEST_ID` (`TENANT_ID`, `MACD_REQUEST_ID`),
  KEY `IDX_MACD_REQUEST_TENANT_ID_MACD_CATALOGUE_ITEM_ID` (`TENANT_ID`, `MACD_CATALOGUE_ITEM_ID`),
  KEY `IDX_MACD_REQUEST_TENANT_ID_INV_SITE_ID_STAGE` (`TENANT_ID`, `INV_SITE_ID`, `STAGE`),
  KEY `IDX_MACD_REQUEST_TENANT_ID_STAGE` (`TENANT_ID`, `STAGE`),
  KEY `IDX_MACD_REQUEST_TENANT_ID_BSS_CUSTOMER_ID` (`TENANT_ID`, `BSS_CUSTOMER_ID`),
  KEY `IDX_MACD_REQUEST_ITSM_CHANGE_ID` (`ITSM_CHANGE_ID`),
  KEY `IDX_MACD_REQUEST_INV_RACK_ID` (`INV_RACK_ID`),
  CONSTRAINT `CK_MACD_REQUEST_01` CHECK (QTY > 0),
  CONSTRAINT `CK_MACD_REQUEST_02` CHECK (NRC_AMOUNT >= 0),
  CONSTRAINT `CK_MACD_REQUEST_03` CHECK (STAGE = 'Draft' OR SUBMITTED_AT IS NOT NULL),
  CONSTRAINT `CK_MACD_REQUEST_04` CHECK (STAGE <> 'Completed' OR COMPLETED_AT IS NOT NULL),
  CONSTRAINT `CK_MACD_REQUEST_05` CHECK (WINDOW_START IS NULL OR WINDOW_END IS NULL OR WINDOW_START < WINDOW_END),
  CONSTRAINT `CK_MACD_REQUEST_06` CHECK (STAGE NOT IN ('Rejected','Cancelled') OR REASON IS NOT NULL),
  CONSTRAINT `FK_MACD_REQUEST_MACD_CATALOGUE_ITEM_ID` FOREIGN KEY (`TENANT_ID`, `MACD_CATALOGUE_ITEM_ID`) REFERENCES `MACD_CATALOGUE_ITEM` (`TENANT_ID`, `MACD_CATALOGUE_ITEM_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='MACD request from a customer or internal team, through stages Draft → … → Completed, with SLA clock and the change it runs under.';

