  `LAST_RUN_AT` DATETIME(3) NULL COMMENT 'Last evaluation',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`COMPLIANCE_POLICY_ID`),
  UNIQUE KEY `UK_COMPLIANCE_POLICY_TENANT_ID_POLICY_CODE` (`TENANT_ID`, `POLICY_CODE`),
  UNIQUE KEY `UK_COMPLIANCE_POLICY_TENANT_ID_COMPLIANCE_POLICY_ID` (`TENANT_ID`, `COMPLIANCE_POLICY_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Identity and run state of a policy as code; content is versioned in COMPLIANCE_POLICY_VERSION (BRD 7.11).';

-- COMPLIANCE_POLICY_VERSION: Version of a policy: Rego package and source, area, enforcement, trigger. Published versions never change.
-- Related tables: COMPLIANCE_POLICY_VERSION → COMPLIANCE_POLICY; ← COMPLIANCE_DECISION
-- Domain: E. MACD, compliance and imports · Updated: 2026-11-12
CREATE TABLE `COMPLIANCE_POLICY_VERSION` (
  `COMPLIANCE_POLICY_VERSION_ID` INT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of COMPLIANCE_POLICY_VERSION',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `COMPLIANCE_POLICY_ID` INT UNSIGNED NOT NULL COMMENT 'Policy',
  `VERSION_NO` SMALLINT UNSIGNED NOT NULL COMMENT 'Version',
  `VERSION_STATUS` ENUM('Draft','Awaiting approval','Published','Superseded','Rejected','Discarded') NOT NULL DEFAULT 'Draft' COMMENT 'State',
  `NAME` VARCHAR(200) NOT NULL COMMENT 'Name',
  `RULE_TEXT` VARCHAR(1000) NOT NULL COMMENT 'Rule in words',
  `AREA` ENUM('Power','Cooling','Network','Lifecycle','Change','Safety','Maintenance') NOT NULL COMMENT 'Area',
  `ENFORCEMENT` ENUM('Block','Warn') NOT NULL COMMENT 'Block stops the change; Warn records it',
  `POLICY_TRIGGER` ENUM('Nightly sweep','On change','Change gate') NOT NULL COMMENT 'When it runs',
  `REGO_PACKAGE` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Rego package',
  `REGO_SOURCE` TEXT NOT NULL COMMENT 'Rego source (policy as code, up to 64 KB)',
  `PUBLISHED_AT` DATETIME(3) NULL COMMENT 'Published',
  `PUBLISHED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Published by',
  `LIVE_KEY` INT UNSIGNED GENERATED ALWAYS AS (IF(VERSION_STATUS = 'Published', COMPLIANCE_POLICY_ID, NULL)) STORED NULL COMMENT 'One published version per policy (generated)',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`COMPLIANCE_POLICY_VERSION_ID`),
  UNIQUE KEY `UK_CPV_TENANT_ID_CP_ID_VERSION_NO` (`TENANT_ID`, `COMPLIANCE_POLICY_ID`, `VERSION_NO`),
  UNIQUE KEY `UK_COMPLIANCE_POLICY_VERSION_LIVE_KEY` (`LIVE_KEY`),
  UNIQUE KEY `UK_CPV_TENANT_ID_CPV_ID` (`TENANT_ID`, `COMPLIANCE_POLICY_VERSION_ID`),
  CONSTRAINT `CK_COMPLIANCE_POLICY_VERSION_01` CHECK (VERSION_STATUS IN ('Draft','Discarded','Rejected','Awaiting approval') OR PUBLISHED_AT IS NOT NULL),
