-- COMPLIANCE_DECISION: Policy decision per resource (deny / warn / allow) with the input it was made on (snapshot, DATA-022).
-- Domain: E. MACD, compliance and imports · Updated: 2026-11-12
CREATE TABLE `COMPLIANCE_DECISION` (
  `COMPLIANCE_DECISION_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of COMPLIANCE_DECISION',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `COMPLIANCE_POLICY_VERSION_ID` INT UNSIGNED NOT NULL COMMENT 'Policy version evaluated',
  `RESOURCE_TYPE` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Resource type (rack, device, change, prefix …)',
  `RESOURCE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Resource id in its module',
  `RESOURCE_NAME` VARCHAR(200) NOT NULL COMMENT 'Name as at the decision (snapshot, never refreshed)',
  `INV_SITE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Site of the resource',
  `POLICY_RESULT` ENUM('allow','deny','warn') NOT NULL COMMENT 'Decision',
  `GATE_OUTCOME` ENUM('Blocked','Warned') NULL COMMENT 'What it did to a change',
  `ITSM_CHANGE_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Change it gated',
  `EVALUATED_AT` DATETIME(3) NOT NULL COMMENT 'When',
  `POLICY_TRIGGER` ENUM('Nightly sweep','On change','Change gate') NOT NULL COMMENT 'What triggered it',
  `INPUT_SNAPSHOT` JSON NOT NULL COMMENT 'OPA input the decision was made on',
  `RESULT_MESSAGE` VARCHAR(1000) NULL COMMENT 'Message',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`COMPLIANCE_DECISION_ID`),
  KEY `IDX_COMPLIANCE_DECISION_TENANT_ID_COMPLIANCE_POLICY_VERSION_ID` (`TENANT_ID`, `COMPLIANCE_POLICY_VERSION_ID`),
  KEY `IDX_COMPLIANCE_DECISION_TENANT_ID_INV_SITE_ID_POLICY_RESULT` (`TENANT_ID`, `INV_SITE_ID`, `POLICY_RESULT`),
  KEY `IDX_COMPLIANCE_DECISION_TENANT_ID_RESOURCE_TYPE_RESOURCE_ID` (`TENANT_ID`, `RESOURCE_TYPE`, `RESOURCE_ID`),
  KEY `IDX_COMPLIANCE_DECISION_ITSM_CHANGE_ID` (`ITSM_CHANGE_ID`),
  CONSTRAINT `CK_COMPLIANCE_DECISION_01` CHECK (POLICY_RESULT = 'allow' OR RESULT_MESSAGE IS NOT NULL),
  CONSTRAINT `CK_COMPLIANCE_DECISION_02` CHECK (GATE_OUTCOME IS NULL OR ITSM_CHANGE_ID IS NOT NULL),
  CONSTRAINT `FK_COMPLIANCE_DECISION_COMPLIANCE_POLICY_VERSION_ID` FOREIGN KEY (`TENANT_ID`, `COMPLIANCE_POLICY_VERSION_ID`) REFERENCES `COMPLIANCE_POLICY_VERSION` (`TENANT_ID`, `COMPLIANCE_POLICY_VERSION_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Policy decision per resource (deny / warn / allow) with the input it was made on (snapshot, DATA-022).';

