  KEY `IDX_IMPORT_BATCH_TENANT_ID_FILE_SHA256` (`TENANT_ID`, `FILE_SHA256`),
  CONSTRAINT `CK_IMPORT_BATCH_01` CHECK (STATUS NOT IN ('Loaded','Partly loaded') OR LOADED_AT IS NOT NULL),
  CONSTRAINT `FK_IMPORT_BATCH_BUSINESS_MODEL_ID` FOREIGN KEY (`TENANT_ID`, `BUSINESS_MODEL_ID`) REFERENCES `BUSINESS_MODEL` (`TENANT_ID`, `BUSINESS_MODEL_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Onboarding workbook upload: file, template, state and the reconciliation report (DATA-012, -013). Loading writes to Inventory / Inventory Planning through their APIs.';

