-- WRITEBACK_REQUEST: Write to a platform module API waiting, done or failed (DEV-07): target API, payload, idempotency key, attempts. Exactly one source column is set.
-- Domain: F. Cross-cutting · Updated: 2026-11-12
CREATE TABLE `WRITEBACK_REQUEST` (
  `WRITEBACK_REQUEST_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of WRITEBACK_REQUEST',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `TARGET_MODULE` ENUM('INV','IPL','IPM','ITSM','ALR','BSS','PRJ','SCM','SOC','PEN','OAP','IHB','AIF') NOT NULL COMMENT 'Module written to',
  `TARGET_API` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'API id from BRD 9.11–9.25 (e.g. API-INV-07)',
  `HTTP_METHOD` ENUM('POST','PUT','PATCH','DELETE') NOT NULL COMMENT 'Method',
  `TARGET_PATH` VARCHAR(500) NOT NULL COMMENT 'Path called',
  `TARGET_RECORD_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Record written (once known)',
  `IDEMPOTENCY_KEY` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Idempotency key sent with every attempt',
  `PAYLOAD` JSON NOT NULL COMMENT 'Request body (no credentials; the service account token is never stored)',
  `DCIM_WORK_ITEM_ID` BIGINT UNSIGNED NULL COMMENT 'Source: DCIM work item',
  `MACD_REQUEST_ID` BIGINT UNSIGNED NULL COMMENT 'Source: MACD request',
  `PLAN_ID` BIGINT UNSIGNED NULL COMMENT 'Source: plan',
  `IMPORT_BATCH_ID` BIGINT UNSIGNED NULL COMMENT 'Source: import batch',
  `INCIDENT_ENRICHMENT_ID` BIGINT UNSIGNED NULL COMMENT 'Source: incident enrichment',
  `SOURCE_NOTE` VARCHAR(200) NULL COMMENT 'Source in words when none of the source columns applies (scheduled evaluation)',
  `STATUS` ENUM('Queued','Sending','Done','Failed','Abandoned') NOT NULL DEFAULT 'Queued' COMMENT 'State',
  `ATTEMPTS` SMALLINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Attempts so far',
  `NEXT_ATTEMPT_AT` DATETIME(3) NULL COMMENT 'Next retry',
  `RESPONSE_STATUS` SMALLINT UNSIGNED NULL COMMENT 'Last HTTP status',
  `LAST_ERROR` VARCHAR(1000) NULL COMMENT 'Last error',
  `DONE_AT` DATETIME(3) NULL COMMENT 'Succeeded',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`WRITEBACK_REQUEST_ID`),
  UNIQUE KEY `UK_WRITEBACK_REQUEST_TENANT_ID_IDEMPOTENCY_KEY` (`TENANT_ID`, `IDEMPOTENCY_KEY`),
  KEY `IDX_WRITEBACK_REQUEST_TENANT_ID_STATUS_NEXT_ATTEMPT_AT` (`TENANT_ID`, `STATUS`, `NEXT_ATTEMPT_AT`),
  KEY `IDX_WRITEBACK_REQUEST_TENANT_ID_DCIM_WORK_ITEM_ID` (`TENANT_ID`, `DCIM_WORK_ITEM_ID`),
  KEY `IDX_WRITEBACK_REQUEST_TENANT_ID_MACD_REQUEST_ID` (`TENANT_ID`, `MACD_REQUEST_ID`),
  KEY `IDX_WRITEBACK_REQUEST_TENANT_ID_PLAN_ID` (`TENANT_ID`, `PLAN_ID`),
  KEY `IDX_WRITEBACK_REQUEST_TENANT_ID_IMPORT_BATCH_ID` (`TENANT_ID`, `IMPORT_BATCH_ID`),
  KEY `IDX_WRITEBACK_REQUEST_TENANT_ID_INCIDENT_ENRICHMENT_ID` (`TENANT_ID`, `INCIDENT_ENRICHMENT_ID`),
  CONSTRAINT `CK_WRITEBACK_REQUEST_01` CHECK ((DCIM_WORK_ITEM_ID IS NOT NULL) + (MACD_REQUEST_ID IS NOT NULL) + (PLAN_ID IS NOT NULL) + (IMPORT_BATCH_ID IS NOT NULL) + (INCIDENT_ENRICHMENT_ID IS NOT NULL) + (SOURCE_NOTE IS NOT NULL) = 1),
  CONSTRAINT `CK_WRITEBACK_REQUEST_02` CHECK (STATUS <> 'Done' OR DONE_AT IS NOT NULL),
  CONSTRAINT `CK_WRITEBACK_REQUEST_03` CHECK (STATUS <> 'Failed' OR LAST_ERROR IS NOT NULL),
  CONSTRAINT `FK_WRITEBACK_REQUEST_DCIM_WORK_ITEM_ID` FOREIGN KEY (`TENANT_ID`, `DCIM_WORK_ITEM_ID`) REFERENCES `DCIM_WORK_ITEM` (`TENANT_ID`, `DCIM_WORK_ITEM_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_WRITEBACK_REQUEST_MACD_REQUEST_ID` FOREIGN KEY (`TENANT_ID`, `MACD_REQUEST_ID`) REFERENCES `MACD_REQUEST` (`TENANT_ID`, `MACD_REQUEST_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_WRITEBACK_REQUEST_PLAN_ID` FOREIGN KEY (`TENANT_ID`, `PLAN_ID`) REFERENCES `PLAN` (`TENANT_ID`, `PLAN_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_WRITEBACK_REQUEST_IMPORT_BATCH_ID` FOREIGN KEY (`TENANT_ID`, `IMPORT_BATCH_ID`) REFERENCES `IMPORT_BATCH` (`TENANT_ID`, `IMPORT_BATCH_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FK_WRITEBACK_REQUEST_INCIDENT_ENRICHMENT_ID` FOREIGN KEY (`TENANT_ID`, `INCIDENT_ENRICHMENT_ID`) REFERENCES `INCIDENT_ENRICHMENT` (`TENANT_ID`, `INCIDENT_ENRICHMENT_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Write to a platform module API waiting, done or failed (DEV-07): target API, payload, idempotency key, attempts. Exactly one source column is set.';

-- USER_PREFERENCE: Per-viewer convenience (list or tiles, open sections, twin view). Optional: browser storage is enough for P1.
-- Domain: F. Cross-cutting · Updated: 2026-11-12
CREATE TABLE `USER_PREFERENCE` (
  `USER_PREFERENCE_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL COMMENT 'Surrogate primary key of USER_PREFERENCE',
  `TENANT_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Operator (tenant) id from Platform Engineering; every query is scoped by it',
  `PE_USER_ID` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User (Platform Engineering)',
  `PREF_KEY` VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Preference key (e.g. dco.pn.layout.plans)',
  `PREF_VALUE` VARCHAR(1000) NOT NULL COMMENT 'Value',
  `CREATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Row created (UTC)',
  `CREATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that created the row (Platform Engineering)',
  `UPDATED_AT` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'Row last changed (UTC)',
  `UPDATED_BY` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User id that last changed the row (Platform Engineering)',
  PRIMARY KEY (`USER_PREFERENCE_ID`),
  UNIQUE KEY `UK_USER_PREFERENCE_TENANT_ID_PE_USER_ID_PREF_KEY` (`TENANT_ID`, `PE_USER_ID`, `PREF_KEY`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Per-viewer convenience (list or tiles, open sections, twin view). Optional: browser storage is enough for P1.';

